import 'package:flutter/rendering.dart';

/// A tile span in grid cells (width × height).
typedef TileSpan = ({int w, int h});

/// Where one tile lands in the grid (0-based row/column of its top-left
/// cell).
typedef TilePlacement = ({int row, int col});

/// iOS-home-screen grid geometry: the grid unit is the APP-ICON SLOT — one
/// icon square ([iconSize]) plus its label strip ([labelHeight]) below.
/// A WxH live tile measures exactly the outer edges of the WxH block of
/// icon slots it replaces, so widget edges always align with icon edges.
abstract final class LauncherGridSpec {
  /// App-icon square side, in logical pixels.
  static const double iconSize = 56;

  /// Height of the label strip under the icon square.
  static const double labelHeight = 20;

  /// Gap between cells, both axes.
  static const double spacing = 16;

  /// Cross-axis extent of one cell (the icon square).
  static const double cellCrossExtent = iconSize;

  /// Main-axis extent of one cell (icon square + label strip).
  static const double cellMainExtent = iconSize + labelHeight;

  /// Cross-axis extent of a [cells]-wide span (including inner gaps).
  static double spanCrossExtent(int cells) =>
      cells * cellCrossExtent + (cells - 1) * spacing;

  /// Main-axis extent of a [cells]-high span (including inner gaps).
  static double spanMainExtent(int cells) =>
      cells * cellMainExtent + (cells - 1) * spacing;

  /// Cross-axis extent of the whole grid at [columns] columns.
  static double gridCrossExtent(int columns) => spanCrossExtent(columns);
}

/// Order-preserving row packing of [spans] into a grid with
/// [crossAxisCount] columns (issue #166): tiles are placed strictly in
/// list order — each tile takes the first free WxH block at or after the
/// previous tile's position (scanning the current row left-to-right, then
/// wrapping to the next row), so placements never go backwards in reading
/// order and the visual order always matches the tile order. A tile that
/// does not fit the remaining cells of a row wraps to the next row and
/// the trailing cells stay blank — iOS-home-screen-like, no backfilling,
/// no reordering. Spans are clamped to the grid (width
/// 1..[crossAxisCount], height at least 1). Child index ↔ span index
/// stays 1:1, so reorder logic is unaffected.
List<TilePlacement> packTileSpans({
  required int crossAxisCount,
  required List<TileSpan> spans,
}) {
  // rows[r][c] = occupied; rows are appended on demand.
  final rows = <List<bool>>[];
  final placements = <TilePlacement>[];
  var cursorRow = 0;
  var cursorCol = 0;
  for (final span in spans) {
    (cursorRow, cursorCol) = _packSpan(
      rows,
      placements,
      crossAxisCount: crossAxisCount,
      span: span,
      cursorRow: cursorRow,
      cursorCol: cursorCol,
    );
  }
  return placements;
}

/// Places ONE span at the first free WxH block at or after the cursor
/// (scanning the current row left-to-right, then wrapping), marks it
/// occupied, records the placement, and returns the advanced cursor.
(int, int) _packSpan(
  List<List<bool>> rows,
  List<TilePlacement> placements, {
  required int crossAxisCount,
  required TileSpan span,
  required int cursorRow,
  required int cursorCol,
}) {
  final w = span.w.clamp(1, crossAxisCount);
  final h = span.h < 1 ? 1 : span.h;
  while (true) {
    _growRows(rows, crossAxisCount: crossAxisCount, rowsNeeded: cursorRow + h);
    if (_spanFits(
      rows,
      crossAxisCount: crossAxisCount,
      row: cursorRow,
      col: cursorCol,
      w: w,
      h: h,
    )) {
      _markSpan(rows, row: cursorRow, col: cursorCol, w: w, h: h);
      placements.add((row: cursorRow, col: cursorCol));
      return (cursorRow, cursorCol + w);
    }
    // Advance along the row; wrap when the span no longer fits.
    if (++cursorCol + w > crossAxisCount) {
      cursorRow++;
      cursorCol = 0;
    }
  }
}

void _growRows(
  List<List<bool>> rows, {
  required int crossAxisCount,
  required int rowsNeeded,
}) {
  while (rows.length < rowsNeeded) {
    rows.add(List<bool>.filled(crossAxisCount, false));
  }
}

bool _spanFits(
  List<List<bool>> rows, {
  required int crossAxisCount,
  required int row,
  required int col,
  required int w,
  required int h,
}) {
  if (col + w > crossAxisCount) return false;
  for (var dr = 0; dr < h; dr++) {
    if (_rowSegmentOccupied(rows[row + dr], col: col, w: w)) return false;
  }
  return true;
}

bool _rowSegmentOccupied(List<bool> row, {required int col, required int w}) {
  for (var dc = 0; dc < w; dc++) {
    if (row[col + dc]) return true;
  }
  return false;
}

void _markSpan(
  List<List<bool>> rows, {
  required int row,
  required int col,
  required int w,
  required int h,
}) {
  for (var dr = 0; dr < h; dr++) {
    for (var dc = 0; dc < w; dc++) {
      rows[row + dr][col + dc] = true;
    }
  }
}

/// The pixel rect (top-left + extent) of one placed tile.
typedef TileRect = ({double x, double y, double w, double h});

/// Lays [spans] out with [packTileSpans] and converts placements to pixel
/// rects on the [LauncherGridSpec] geometry ([spacing] overrides the spec's
/// default CROSS-axis gap — the launcher stretches gaps to fill the screen
/// width, iOS-like; [mainAxisSpacing] is the row gap, kept tight):
/// x/y are the top-left of the tile's slot block, w/h the exact WxH block
/// extent.
List<TileRect> layOutTileRects({
  required int crossAxisCount,
  required List<TileSpan> spans,
  double spacing = LauncherGridSpec.spacing,
  double mainAxisSpacing = LauncherGridSpec.spacing,
}) {
  final placements = packTileSpans(
    crossAxisCount: crossAxisCount,
    spans: spans,
  );
  double spanCross(int cells) =>
      cells * LauncherGridSpec.cellCrossExtent + (cells - 1) * spacing;
  double spanMain(int cells) =>
      cells * LauncherGridSpec.cellMainExtent + (cells - 1) * mainAxisSpacing;
  return [
    for (var i = 0; i < spans.length; i++)
      (
        x: placements[i].col * (LauncherGridSpec.cellCrossExtent + spacing),
        y:
            placements[i].row *
            (LauncherGridSpec.cellMainExtent + mainAxisSpacing),
        w: spanCross(spans[i].w.clamp(1, crossAxisCount)),
        h: spanMain(spans[i].h < 1 ? 1 : spans[i].h),
      ),
  ];
}

/// The total main-axis extent needed to show every rect of [layOutTileRects]
/// (0 for an empty grid).
double packedTilesHeight(List<TileRect> rects) {
  var max = 0.0;
  for (final rect in rects) {
    final bottom = rect.y + rect.h;
    if (bottom > max) max = bottom;
  }
  return max;
}

/// Maps a grid-local [pointer] to `(targetKey, fx)` for the launcher's
/// background-hover preview (issue #166): above the first row → before
/// the first tile; inside a row → the tile whose center is right of the
/// pointer (or after the row's last); below → after the last. Rows are
/// grouped by y because first-fit packing backfills holes (y is NOT
/// monotonic in index).
(String, double) launcherGridHoverTarget({
  required Offset pointer,
  required List<String> keys,
  required List<TileRect> rects,
}) {
  final rowTops = <double>{for (final r in rects) r.y}.toList()..sort();
  if (pointer.dy < rowTops.first) return (keys.first, 0);
  for (final top in rowTops) {
    if (pointer.dy > _rowBottom(rects, top)) continue;
    return _scanHoverRow(pointer, keys, rects, top);
  }
  return (keys.last, 1);
}

/// First tile of [top]'s row whose center is right of the pointer
/// inserts before it (fx 0); past them all inserts after the row's last
/// (fx 1).
(String, double) _scanHoverRow(
  Offset pointer,
  List<String> keys,
  List<TileRect> rects,
  double top,
) {
  final indices = _hoverRowIndices(rects, top);
  for (final i in indices) {
    if (pointer.dx < rects[i].x + rects[i].w / 2) return (keys[i], 0);
  }
  return (keys[indices.last], 1);
}

/// Indices of the rects starting at row [top], left-to-right.
List<int> _hoverRowIndices(List<TileRect> rects, double top) {
  final indices = <int>[
    for (var i = 0; i < rects.length; i++)
      if (rects[i].y == top) i,
  ];
  indices.sort((a, b) => rects[a].x.compareTo(rects[b].x));
  return indices;
}

/// The lowest bottom edge among the rects starting at row [top].
double _rowBottom(List<TileRect> rects, double top) {
  var bottom = top;
  for (final r in rects) {
    if (r.y != top) continue;
    bottom = r.y + r.h > bottom ? r.y + r.h : bottom;
  }
  return bottom;
}

/// Rectangular-cell grid delegate with per-child spans (see [packTileSpans])
/// on the [LauncherGridSpec] icon-unit geometry. A WxH tile measures
/// `W` × `H` cells plus the inter-cell spacing inside the span.
class SpanGridDelegate extends SliverGridDelegate {
  SpanGridDelegate({
    required this.crossAxisCount,
    required this.spans,
    this.crossAxisCellExtent = LauncherGridSpec.cellCrossExtent,
    this.mainAxisCellExtent = LauncherGridSpec.cellMainExtent,
    this.spacing = LauncherGridSpec.spacing,
  });

  /// Fixed column count (derived from the available width by the caller).
  final int crossAxisCount;

  /// Per-child spans, indexed like the grid's children.
  final List<TileSpan> spans;

  /// Cross-axis extent of one cell (the icon square on the launcher).
  final double crossAxisCellExtent;

  /// Main-axis extent of one cell (icon square + label strip).
  final double mainAxisCellExtent;

  /// Gap between cells (applied inside spans too).
  final double spacing;

  @override
  SliverGridLayout getLayout(SliverConstraints constraints) {
    final placements = packTileSpans(
      crossAxisCount: crossAxisCount,
      spans: spans,
    );
    return _SpanGridLayout([
      for (var i = 0; i < spans.length; i++)
        (
          x: placements[i].col * (crossAxisCellExtent + spacing),
          y: placements[i].row * (mainAxisCellExtent + spacing),
          w: _spanExtent(
            spans[i].w.clamp(1, crossAxisCount),
            crossAxisCellExtent,
          ),
          h: _spanExtent(spans[i].h < 1 ? 1 : spans[i].h, mainAxisCellExtent),
        ),
    ]);
  }

  double _spanExtent(int cells, double cell) =>
      cells * cell + (cells - 1) * spacing;

  @override
  bool shouldRelayout(SpanGridDelegate oldDelegate) {
    if (crossAxisCount != oldDelegate.crossAxisCount ||
        crossAxisCellExtent != oldDelegate.crossAxisCellExtent ||
        mainAxisCellExtent != oldDelegate.mainAxisCellExtent ||
        spacing != oldDelegate.spacing ||
        spans.length != oldDelegate.spans.length) {
      return true;
    }
    for (var i = 0; i < spans.length; i++) {
      if (spans[i] != oldDelegate.spans[i]) return true;
    }
    return false;
  }
}

class _SpanGridLayout extends SliverGridLayout {
  const _SpanGridLayout(this._tiles);

  /// Per-child geometry: top-left offset + extent, in pixels. Note y is NOT
  /// monotonic in index (first-fit backfills holes), so the scroll-offset
  /// queries scan linearly — the grid is a screenful of tiles, not a list.
  final List<TileRect> _tiles;

  @override
  int getMinChildIndexForScrollOffset(double scrollOffset) {
    for (var i = 0; i < _tiles.length; i++) {
      if (_tiles[i].y + _tiles[i].h > scrollOffset) return i;
    }
    return _lastTileIndex();
  }

  /// The bottom-most child when the offset is past every tile (gh-1848
  /// split): y is not monotonic in index (first-fit backfills holes), so
  /// an overshoot pins the LAST tile, not the tallest.
  int _lastTileIndex() => _tiles.isEmpty ? 0 : _tiles.length - 1;

  @override
  int getMaxChildIndexForScrollOffset(double scrollOffset) {
    for (var i = _tiles.length - 1; i >= 0; i--) {
      if (_tiles[i].y < scrollOffset) return i;
    }
    return 0;
  }

  @override
  SliverGridGeometry getGeometryForChildIndex(int index) {
    final tile = _tiles[index];
    return SliverGridGeometry(
      scrollOffset: tile.y,
      crossAxisOffset: tile.x,
      mainAxisExtent: tile.h,
      crossAxisExtent: tile.w,
    );
  }

  @override
  double computeMaxScrollOffset(int childCount) => packedTilesHeight(_tiles);
}

