import 'dart:async';

import 'package:fa/l10n/l10n_ext.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

import 'package:fa/services/agent_service.dart';
import 'package:fa/gemma/gemma_service.dart';
import 'package:fa/gemma/gemma_types.dart';
import 'package:fa/transformers_js/transformers_js_service.dart';
import 'package:fa/transformers_js/transformers_js_types.dart';
import 'package:fa/webllm/webllm_service.dart';
import 'package:fa/webllm/webllm_types.dart';

/// Which on-device engine a quick-start row belongs to.
enum _QuickStartKind { webllm, gemma, transformersJs }

/// One row in the quick-start section: a model whose weights are already on
/// this device/browser, ready to load without a download.
final class _QuickStartEntry {
  const _QuickStartEntry({
    required this.kind,
    required this.preset,
    required this.title,
    required this.sizeLabel,
    this.bytes,
  });

  final _QuickStartKind kind;

  /// The model preset (`WebLlmModelPreset` / `GemmaModelPreset` /
  /// `TransformersJsModelPreset`, matched by [kind]).
  final Object preset;

  /// Row title (the preset's display name).
  final String title;

  /// Approximate download size, shown when no exact byte count is known.
  final String sizeLabel;

  /// Exact cached/installed byte count when cheaply known.
  final int? bytes;
}

/// The "Downloaded models" section on the setup screen: one row per
/// on-device model whose weights are already cached/installed here (WebLLM
/// and transformers.js CacheStorage on web, the flutter_gemma repository on
/// mobile), each with a one-tap "Use" action that loads the model (no
/// download, no API key) and connects straight away.
///
/// The section is hidden while the scan runs and when nothing is downloaded
/// — first-run users never see it. The scan only queries cache state; it
/// never loads a model into the (singleton) engines, so the engines stay
/// cold until a "Use" tap warms exactly the picked model (which the later
/// chat stream function then reuses).
class DownloadedModelsQuickStart extends StatefulWidget {
  const DownloadedModelsQuickStart({
    super.key,
    required this.onConnect,
    this.webLlmEngine,
    this.gemmaEngine,
    this.transformersJsEngine,
    this.isWeb,
  });

  /// Called with the assembled [AgentConfig] after the picked model loaded.
  /// Throw to surface an error in the section; return normally on success.
  final Future<void> Function(AgentConfig config) onConnect;

  /// Engine overrides for tests; default to the platform singletons.
  final WebLlmEngineApi? webLlmEngine;
  final GemmaEngineApi? gemmaEngine;
  final TransformersJsEngineApi? transformersJsEngine;

  /// Platform override for tests (the Gemma install file names differ per
  /// platform — the same seam as `GemmaCacheSection.isWeb`).
  final bool? isWeb;

  @override
  State<DownloadedModelsQuickStart> createState() =>
      _DownloadedModelsQuickStartState();
}

class _DownloadedModelsQuickStartState
    extends State<DownloadedModelsQuickStart> {
  late final WebLlmEngineApi _webLlm =
      widget.webLlmEngine ?? createWebLlmService();
  late final GemmaEngineApi _gemma = widget.gemmaEngine ?? createGemmaService();
  late final TransformersJsEngineApi _transformersJs =
      widget.transformersJsEngine ?? createTransformersJsService();
  late final bool _isWeb = widget.isWeb ?? kIsWeb;

  /// Rows from the last scan; `null` while the scan runs (section hidden).
  List<_QuickStartEntry>? _entries;

  /// The manual timer behind [_installedModelsBounded] — cancelled on
  /// dispose so a wedged plugin never leaves a pending timer behind
  /// (`Future.timeout`'s internal timer cannot be cancelled).
  Timer? _gemmaScanTimer;

  bool _busy = false;
  double? _loadFraction;
  String? _loadStatus;
  String? _error;

  /// Upper bound for the Gemma repository scan: a hung store (OPFS lock,
  /// dead plugin channel) must not pin the section (same bound as the Gemma
  /// cache section).
  static const _scanTimeout = Duration(seconds: 10);

  @override
  void initState() {
    super.initState();
    unawaited(_scan());
  }

  @override
  void dispose() {
    _gemmaScanTimer?.cancel();
    super.dispose();
  }

  /// [GemmaEngineApi.installedModels] with the [_scanTimeout] bound, but on
  /// a [Timer] this State owns (and cancels in [dispose]).
  Future<List<GemmaInstalledModel>> _installedModelsBounded(
    GemmaEngineApi engine,
  ) {
    final completer = Completer<List<GemmaInstalledModel>>();
    _gemmaScanTimer = Timer(_scanTimeout, () {
      if (!completer.isCompleted) {
        completer.completeError(
          TimeoutException('Gemma repository scan timed out', _scanTimeout),
        );
      }
    });
    unawaited(
      engine.installedModels().then(
        (models) {
          if (!completer.isCompleted) completer.complete(models);
        },
        onError: (Object error) {
          if (!completer.isCompleted) completer.completeError(error);
        },
      ),
    );
    return completer.future;
  }

  Future<void> _scan() async {
    final entries = <_QuickStartEntry>[];
    if (_webLlm.isAvailable) {
      for (final preset in webLlmModelPresets) {
        final info = await _queryCache(() => _webLlm.modelCacheInfo(preset.id));
        if (info != null && info.cached) {
          entries.add(
            _QuickStartEntry(
              kind: _QuickStartKind.webllm,
              preset: preset,
              title: preset.displayName,
              sizeLabel: preset.sizeLabel,
              bytes: info.bytes,
            ),
          );
        }
      }
    }
    if (_transformersJs.isAvailable) {
      for (final preset in transformersJsModelPresets) {
        final info = await _queryCache(
          () => _transformersJs.modelCacheInfo(preset.id),
        );
        if (info != null && info.cached) {
          entries.add(
            _QuickStartEntry(
              kind: _QuickStartKind.transformersJs,
              preset: preset,
              title: preset.displayName,
              sizeLabel: preset.sizeLabel,
              bytes: info.bytes,
            ),
          );
        }
      }
    }
    if (_gemma.isAvailable) {
      try {
        final installed = await _installedModelsBounded(_gemma);
        for (final preset in gemmaModelPresets) {
          final filename = preset.filenameFor(isWeb: _isWeb);
          GemmaInstalledModel? match;
          for (final model in installed) {
            if (model.filename == filename) match = model;
          }
          if (match != null) {
            entries.add(
              _QuickStartEntry(
                kind: _QuickStartKind.gemma,
                preset: preset,
                title: preset.displayName,
                sizeLabel: preset.sizeLabelFor(isWeb: _isWeb),
                bytes: match.sizeBytes,
              ),
            );
          }
        }
      } on Object {
        // A failed repository scan yields no Gemma rows, not an error — the
        // full connection form below still offers every provider.
      } finally {
        _gemmaScanTimer?.cancel();
      }
    }
    if (mounted) setState(() => _entries = entries);
  }

  /// Cache queries are best effort: a blocked storage API hides the row
  /// rather than breaking the scan (mirrors the cache sections' `null`
  /// handling).
  Future<T?> _queryCache<T>(Future<T?> Function() query) async {
    try {
      return await query();
    } on Object {
      return null;
    }
  }

  Future<void> _use(_QuickStartEntry entry) async {
    setState(() {
      _busy = true;
      _error = null;
      _loadFraction = null;
      _loadStatus = null;
    });
    try {
      final config = await switch (entry.kind) {
        _QuickStartKind.webllm => _loadWebLlm(
          entry.preset as WebLlmModelPreset,
        ),
        _QuickStartKind.gemma => _loadGemma(entry.preset as GemmaModelPreset),
        _QuickStartKind.transformersJs => _loadTransformersJs(
          entry.preset as TransformersJsModelPreset,
        ),
      };
      if (!mounted) return;
      await widget.onConnect(config);
    } catch (e) {
      if (mounted) {
        setState(() => _error = e is StateError ? e.message : e.toString());
      }
    } finally {
      if (mounted) {
        setState(() {
          _busy = false;
          _loadFraction = null;
          _loadStatus = null;
        });
      }
    }
  }

  /// Loads a cached WebLLM model (weights already in CacheStorage, so this
  /// pays shader compilation only) and builds its [AgentConfig] — the same
  /// shape the settings form's on-device connect produces.
  Future<AgentConfig> _loadWebLlm(WebLlmModelPreset preset) async {
    final sub = _webLlm.progressEvents.listen(_onWebLlmProgress);
    try {
      await _webLlm.loadModel(preset);
    } finally {
      // Not awaited — see the settings form's connect flow (zone-scheduled
      // cancel futures can stall widget tests).
      unawaited(sub.cancel());
    }
    return AgentConfig(
      providerKind: webLlmProviderKind,
      modelId: preset.id,
      baseUrl: '',
      apiKey: '',
      contextWindow: preset.contextWindow,
      maxTokens: 1024,
    );
  }

  /// Marks an installed Gemma model active and loads it (install skips what
  /// is already on disk — no token, no download) and builds its
  /// [AgentConfig].
  Future<AgentConfig> _loadGemma(GemmaModelPreset preset) async {
    final sub = _gemma.progressEvents.listen(_onGemmaProgress);
    try {
      await _gemma.installModel(preset);
      await _gemma.loadModel(preset);
    } finally {
      unawaited(sub.cancel());
    }
    return AgentConfig(
      providerKind: gemmaProviderKind,
      modelId: preset.id,
      baseUrl: '',
      apiKey: '',
      contextWindow: preset.contextWindow,
      maxTokens: 1024,
    );
  }

  /// Loads a cached transformers.js model (ONNX weights already in
  /// CacheStorage) and builds its [AgentConfig].
  Future<AgentConfig> _loadTransformersJs(
    TransformersJsModelPreset preset,
  ) async {
    final sub = _transformersJs.progressEvents.listen(
      _onTransformersJsProgress,
    );
    try {
      await _transformersJs.loadModel(preset);
    } finally {
      unawaited(sub.cancel());
    }
    return AgentConfig(
      providerKind: transformersJsProviderKind,
      modelId: preset.id,
      baseUrl: '',
      apiKey: '',
      contextWindow: preset.contextWindow,
      maxTokens: 1024,
      supportsImages: preset.supportsVision,
    );
  }

  void _onWebLlmProgress(WebLlmProgress report) {
    if (!mounted) return;
    setState(() {
      _loadFraction = report.fraction;
      _loadStatus = report.text;
    });
  }

  void _onGemmaProgress(GemmaProgress report) {
    if (!mounted) return;
    setState(() {
      _loadFraction = report.fraction;
      _loadStatus = report.text;
    });
  }

  void _onTransformersJsProgress(TransformersJsProgress report) {
    if (!mounted) return;
    setState(() {
      _loadFraction = report.fraction;
      _loadStatus = report.text;
    });
  }

  @override
  Widget build(BuildContext context) {
    final entries = _entries;
    // Hidden while scanning and when nothing is downloaded.
    if (entries == null || entries.isEmpty) {
      return const SizedBox.shrink();
    }
    final theme = Theme.of(context);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(context.l10n.quickStartTitle, style: theme.textTheme.titleSmall),
        const SizedBox(height: 4),
        Text(context.l10n.quickStartSubtitle, style: theme.textTheme.bodySmall),
        const SizedBox(height: 4),
        for (final entry in entries)
          ListTile(
            dense: true,
            contentPadding: EdgeInsets.zero,
            title: Text(entry.title),
            subtitle: Text(
              entry.bytes != null
                  ? context.l10n.quickStartCachedLabel(
                      _formatBytes(entry.bytes!),
                      entry.sizeLabel,
                    )
                  : entry.sizeLabel,
            ),
            trailing: FilledButton.tonal(
              onPressed: _busy ? null : () => _use(entry),
              child: Text(context.l10n.quickStartUse),
            ),
          ),
        if (_busy) ...[
          const SizedBox(height: 4),
          LinearProgressIndicator(value: _loadFraction),
          const SizedBox(height: 4),
          Text(
            _loadStatus != null && _loadStatus!.isNotEmpty
                ? _loadStatus!
                : context.l10n.quickStartLoading,
            style: theme.textTheme.bodySmall,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
          ),
        ],
        if (_error != null) ...[
          const SizedBox(height: 4),
          Text(_error!, style: TextStyle(color: theme.colorScheme.error)),
        ],
        const SizedBox(height: 8),
        const Divider(),
        const SizedBox(height: 16),
      ],
    );
  }
}

/// Human-readable byte count for cached-weights sizes (`1.2 GB`, `750 MB`).
String _formatBytes(int bytes) {
  if (bytes >= 1 << 30) return '${(bytes / (1 << 30)).toStringAsFixed(1)} GB';
  if (bytes >= 1 << 20) return '${bytes ~/ (1 << 20)} MB';
  if (bytes >= 1 << 10) return '${bytes ~/ (1 << 10)} KB';
  return '$bytes B';
}

import 'package:fa/l10n/l10n_ext.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

import 'package:fa/ui/widgets/file_preview.dart';
import 'package:fa/services/icloud_sync_service.dart';
import 'package:fa/services/project_folder_channel.dart';
import 'package:fa/services/project_mount_env.dart';
import 'package:fa/services/project_mount_flow.dart';
import 'package:fa/services/upload.dart';
import 'package:fa/services/upload_picker_stub.dart'
    if (dart.library.html) 'package:fa/services/upload_picker_web.dart';
import 'package:fa_ui/fa_ui.dart' hide formatFileSize;

/// The default [ProjectFolderOps] on supported platforms (macOS), else null.
ProjectFolderOps? _defaultProjectFolderOps() =>
    ProjectFolderChannelOps.isSupported
    ? const ProjectFolderChannelOps()
    : null;

/// Width of the file browser panel (right side panel on wide layouts, end
/// drawer on narrow ones).
const double kFileBrowserPanelWidth = 300;

/// File browser over the agent's [ExecutionEnv].
///
/// Folders navigate (breadcrumb + up), files open a preview — inline in the
/// panel when [inlinePreview] is true (wide layouts), or as a pushed
/// [FilePreviewScreen] route otherwise (narrow layouts).
///
/// The header offers an upload button (when an [UploadPicker] is available,
/// i.e. on web or when one is injected) that writes picked files into the
/// currently viewed folder, so they land in the same sandbox filesystem the
/// agent's tools see.
///
/// When [fsRevision] is provided (see `AgentService.fsRevision`), every
/// bump refreshes the current directory listing and reloads the open
/// preview — that is how the browser learns the agent changed files,
/// without polling.
///
/// Typed against the [ExecutionEnv] abstraction only, so a cloud-backed env
/// can drop in later without UI changes. Navigation uses paths relative to
/// the env's working directory (never [FileInfo.path]): relative paths
/// resolve against the sandbox root on every backend, whereas returned
/// absolute paths are not portable across envs (e.g. the mobile sandbox maps
/// `/`-rooted paths onto a host directory).
class FileBrowser extends StatefulWidget {
  const FileBrowser({
    super.key,
    required this.env,
    this.inlinePreview = true,
    this.uploadPicker,
    this.iCloudSyncService,
    this.maxUploadBatchBytes = kMaxUploadBatchBytes,
    this.fsRevision,
    this.htmlPreviewBuilder,
    this.projectFolderOps,
    this.onProjectMountChanged,
  });

  /// The environment whose filesystem is browsed — the same instance the
  /// agent's tools use (see `AgentService.env`).
  final ExecutionEnv env;

  /// Whether file previews render inside the panel (true) or push a
  /// full-screen route (false).
  final bool inlinePreview;

  /// File chooser behind the upload button. Defaults to the platform picker
  /// (`null` off the web → the button is hidden); tests inject a fake.
  final UploadPicker? uploadPicker;

  /// iCloud sync backend behind the header's sync button. Defaults to the
  /// platform service (`null` off macOS/iOS → the button is hidden); tests
  /// inject a fake (same pattern as [uploadPicker]).
  final ICloudSyncService? iCloudSyncService;

  /// Total-byte cap for one upload batch; oversized batches are refused
  /// with a message before anything is written.
  final int maxUploadBatchBytes;

  /// Agent filesystem revision: every bump reloads the listing and the open
  /// preview. `null` disables auto-refresh (manual refresh still works).
  final ValueListenable<int>? fsRevision;

  /// Override for the HTML rendering surface; tests inject a fake because
  /// the webview plugin has no platform implementation on the host.
  final HtmlPreviewBuilder? htmlPreviewBuilder;

  /// Native project-folder operations behind the open-folder control
  /// (macOS sandbox flow); defaults to the channel ops when supported.
  /// Tests inject a fake.
  final ProjectFolderOps? projectFolderOps;

  /// Fired after the project-folder mount changes (mount/unmount), so the
  /// host can recompose the agent's system prompt.
  final void Function()? onProjectMountChanged;

  @override
  State<FileBrowser> createState() => _FileBrowserState();
}

class _FileBrowserState extends State<FileBrowser> {
  /// Current directory as segments relative to the env root (`[]` = root).
  final List<String> _segments = [];

  List<FileInfo>? _entries;
  String? _error;

  /// The mount env when the agent's env is one (desktop/macOS); null
  /// elsewhere (the open-folder control hides then). Looks through the
  /// [SecretsExecutionEnv] wrapper the agent service always puts around
  /// the shared env.
  ProjectMountEnv? get _mountEnv {
    var env = widget.env;
    if (env is SecretsExecutionEnv) env = env.delegate;
    return env is ProjectMountEnv ? env : null;
  }

  Future<void> _pickProjectFolder() async {
    final ops = widget.projectFolderOps ?? _defaultProjectFolderOps();
    final String? picked;
    try {
      picked = await pickAndApplyProjectMount(
        env: widget.env,
        ops: ops,
        onApplied: () => widget.onProjectMountChanged?.call(),
        onAccessDenied: () {
          if (mounted) {
            showFahErrorSnack(context, context.l10n.filesFolderAccessDenied);
          }
        },
      );
    } on Object catch (e) {
      if (mounted) {
        showFahErrorSnack(
          context,
          context.l10n.filesFolderPickerError(e.toString()),
        );
      }
      return;
    }
    if (picked == null) return;
    setState(() {});
    await _load();
  }

  Future<void> _unmountProjectFolder() async {
    final cleared = await unapplyProjectMount(
      env: widget.env,
      ops: widget.projectFolderOps ?? _defaultProjectFolderOps(),
      onApplied: () => widget.onProjectMountChanged?.call(),
    );
    if (!cleared) return;
    setState(() {});
    await _load();
  }

  bool _loading = true;

  /// Inline preview target, when [FileBrowser.inlinePreview] is on.
  ({String path, String name})? _preview;

  /// Counter folded into the inline preview's key: bumping it forces the
  /// preview to re-read its file (agent-side mutation hook).
  int _previewRevision = 0;

  /// Resolved picker: the injected one, else the platform default (`null`
  /// off the web, which hides the upload button).
  late final UploadPicker? _picker =
      widget.uploadPicker ?? createUploadPicker();

  /// iCloud sync backend behind the header's sync button; `null` off
  /// macOS/iOS (web/Android), which hides the button. Manual trigger only.
  late final ICloudSyncService? _iCloudSync =
      widget.iCloudSyncService ??
      (icloudSyncSupported ? createICloudSyncService(widget.env) : null);

  @override
  void initState() {
    super.initState();
    widget.fsRevision?.addListener(_onFsRevision);
    _load();
  }

  @override
  void didUpdateWidget(FileBrowser oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.fsRevision != widget.fsRevision) {
      oldWidget.fsRevision?.removeListener(_onFsRevision);
      widget.fsRevision?.addListener(_onFsRevision);
    }
  }

  @override
  void dispose() {
    widget.fsRevision?.removeListener(_onFsRevision);
    super.dispose();
  }

  /// Agent-side filesystem change ("hook"): reload the listing and force
  /// the open preview to re-read its file. Conservative — a bump does not
  /// say which file changed (`bash` can touch anything), and one extra
  /// listDir/read is cheap.
  void _onFsRevision() {
    if (_preview != null) _previewRevision++;
    _load();
  }

  /// Path of the current directory in the env namespace, relative to its
  /// working directory.
  String get _envPath => _segments.isEmpty ? '.' : _segments.join('/');

  String _childPath(String name) =>
      _segments.isEmpty ? name : '${_segments.join('/')}/$name';

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final result = await widget.env.listDir(_envPath);
      if (!mounted) return;
      final entries = result.valueOrNull;
      if (entries == null) {
        setState(() {
          _entries = null;
          _loading = false;
          _error =
              result.errorOrNull?.message ?? context.l10n.filesListFolderError;
        });
        return;
      }
      int byName(FileInfo a, FileInfo b) =>
          a.name.toLowerCase().compareTo(b.name.toLowerCase());
      final dirs = entries.where((e) => e.kind == FileKind.directory).toList()
        ..sort(byName);
      final files = entries.where((e) => e.kind != FileKind.directory).toList()
        ..sort(byName);
      setState(() {
        _entries = [...dirs, ...files];
        _loading = false;
      });
    } on Object catch (e) {
      // Defensive: FileSystem operations are contract-bound to return Err
      // instead of throwing; keep the UI alive if a backend misbehaves.
      if (!mounted) return;
      setState(() {
        _entries = null;
        _loading = false;
        _error = e.toString();
      });
    }
  }

  void _enterDir(FileInfo info) {
    setState(() {
      _segments.add(info.name);
      _preview = null;
    });
    _load();
  }

  void _goUp() {
    if (_segments.isEmpty) return;
    setState(() {
      _segments.removeLast();
      _preview = null;
    });
    _load();
  }

  /// Jumps to the breadcrumb at [index] (-1 = root).
  void _jumpTo(int index) {
    setState(() {
      _segments.removeRange(index + 1, _segments.length);
      _preview = null;
    });
    _load();
  }

  void _openFile(FileInfo info) {
    final path = _childPath(info.name);
    if (widget.inlinePreview) {
      setState(() => _preview = (path: path, name: info.name));
    } else {
      Navigator.of(context).push(
        MaterialPageRoute<void>(
          builder: (_) => FilePreviewScreen(
            env: widget.env,
            path: path,
            name: info.name,
            htmlPreviewBuilder: widget.htmlPreviewBuilder,
            fsRevision: widget.fsRevision,
          ),
        ),
      );
    }
  }

  void _showSnack(String message, {bool error = false}) {
    error
        ? showFahErrorSnack(
            context,
            message,
            duration: const Duration(seconds: 3),
            hideCurrent: true,
          )
        : showFahSnack(context, message, duration: const Duration(seconds: 3));
  }

  /// Runs one iCloud merge of the sandbox sessions/apps trees and reports
  /// the outcome as a snackbar (synced counts, or the unavailable guidance
  /// when the ubiquity container is missing).
  Future<void> _syncICloud() async {
    final service = _iCloudSync;
    if (service == null) return;
    await _runSync(service);
  }

  /// Guarded sync body: availability check, one merge, then the outcome
  /// snackbar + reload (extracted so [_syncICloud] stays a thin guard).
  Future<void> _runSync(ICloudSyncService service) async {
    if (!await service.isAvailable()) {
      if (mounted) _showSyncUnavailable();
      return;
    }
    try {
      final report = await service.syncNow();
      if (!mounted) return;
      _showSyncDone(report);
      await _load();
    } on Object catch (e) {
      if (mounted) _showSyncFailed(e);
    }
  }

  void _showSyncUnavailable() =>
      _showSnack(context.l10n.filesICloudSyncUnavailable, error: true);

  void _showSyncDone(ICloudSyncReport report) => _showSnack(
    context.l10n.filesICloudSyncDone(
      report.filesCopied,
      formatFileSize(report.bytesCopied),
      formatICloudSyncTimestamp(report.syncedAt),
    ),
  );

  void _showSyncFailed(Object e) =>
      _showSnack(context.l10n.filesICloudSyncFailed(e.toString()), error: true);

  /// Picks files and writes them into the currently viewed folder of the
  /// sandbox filesystem, so the agent can work with them right away.
  Future<void> _upload() async {
    final picker = _picker;
    if (picker == null) return;
    final List<UploadFile> picked;
    try {
      picked = await picker.pick();
    } on Object catch (e) {
      if (mounted) {
        _showSnack(context.l10n.filesUploadFailed(e.toString()), error: true);
      }
      return;
    }
    if (picked.isEmpty || !mounted) return;

    final sizeError = uploadBatchSizeError(
      picked,
      maxBytes: widget.maxUploadBatchBytes,
      message: (total, max) => context.l10n.uploadTooLarge(max, total),
    );
    if (sizeError != null) {
      _showSnack(sizeError, error: true);
      return;
    }

    var written = 0;
    final failed = <String>[];
    final emptyName = context.l10n.filesEmptyFileName;
    for (final file in picked) {
      final name = sanitizeUploadName(file.name);
      if (name.isEmpty) {
        failed.add(file.name.isEmpty ? emptyName : file.name);
        continue;
      }
      final result = await widget.env.writeBinaryFile(
        _childPath(name),
        file.bytes,
      );
      if (result.isOk) {
        written++;
      } else {
        failed.add(name);
      }
    }
    if (!mounted) return;
    if (written > 0) await _load();
    if (!mounted) return;
    // Failures stay visible: which files, not just how many.
    final failures = failed.isNotEmpty
        ? context.l10n.filesUploadFailures(
            failed.length.toString(),
            failed.join(', '),
          )
        : '';
    _showSnack(context.l10n.filesUploadSummary(failures, written));
  }

  IconData _iconFor(FileInfo info) {
    if (info.kind == FileKind.directory) return Icons.folder_outlined;
    return switch (fileExtension(info.name)) {
      '.png' || '.jpg' || '.jpeg' || '.gif' || '.webp' => Icons.image_outlined,
      _ => Icons.insert_drive_file_outlined,
    };
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _buildHeader(context),
        _buildPathBar(context),
        const Divider(height: 1),
        Expanded(child: _buildBody(context)),
      ],
    );
  }

  Widget _buildHeader(BuildContext context) {
    final theme = Theme.of(context);
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 12, 4, 0),
      child: Row(
        children: [
          Icon(Icons.folder_open_outlined, size: 20, color: theme.hintColor),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              context.l10n.filesPanelTitle,
              style: theme.textTheme.titleMedium,
            ),
          ),
          ?_buildMountControl(context),
          if (_picker != null)
            IconButton(
              icon: const Icon(Icons.upload_file),
              tooltip: context.l10n.filesUploadTooltip,
              onPressed: _upload,
            ),
          if (_iCloudSync != null)
            IconButton(
              icon: const Icon(Icons.cloud_sync_outlined),
              tooltip: context.l10n.filesICloudSyncTooltip,
              onPressed: _syncICloud,
            ),
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: context.l10n.filesRefreshTooltip,
            onPressed: _load,
          ),
        ],
      ),
    );
  }

  /// The project-folder control for the header (macOS sandbox): an
  /// open-folder button when unmounted, a name+eject chip when mounted, a
  /// warning chip when the stored folder became unavailable. Null when the
  /// env has no mount support (web/mobile).
  Widget? _buildMountControl(BuildContext context) {
    final mountEnv = _mountEnv;
    if (mountEnv == null) return null;
    final unavailable = mountEnv.mountUnavailable;
    if (unavailable != null) {
      return IconButton(
        icon: Icon(
          Icons.warning_amber_outlined,
          color: Theme.of(context).colorScheme.error,
        ),
        tooltip: context.l10n.filesMountUnavailableTooltip(unavailable),
        onPressed: _pickProjectFolder,
      );
    }
    final mountedPath = mountEnv.mountedRoot;
    if (mountedPath != null) {
      final name = mountedPath.split('/').where((part) => part.isNotEmpty).last;
      return Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(name, style: Theme.of(context).textTheme.bodySmall),
          IconButton(
            icon: const Icon(Icons.eject_outlined),
            tooltip: context.l10n.filesUnmountTooltip(mountedPath),
            onPressed: _unmountProjectFolder,
          ),
        ],
      );
    }
    final canPick =
        widget.projectFolderOps != null || ProjectFolderChannelOps.isSupported;
    if (!canPick) return null;
    return IconButton(
      icon: const Icon(Icons.create_new_folder_outlined),
      tooltip: context.l10n.filesOpenProjectFolderTooltip,
      onPressed: _pickProjectFolder,
    );
  }

  Widget _buildPathBar(BuildContext context) {
    return SizedBox(
      height: 44,
      child: Row(
        children: [
          IconButton(
            icon: const Icon(Icons.arrow_upward, size: 18),
            tooltip: context.l10n.filesUpTooltip,
            onPressed: _segments.isEmpty ? null : _goUp,
          ),
          Expanded(
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              child: Row(children: _breadcrumbs(context)),
            ),
          ),
        ],
      ),
    );
  }

  List<Widget> _breadcrumbs(BuildContext context) {
    final theme = Theme.of(context);
    final style = theme.textTheme.bodySmall;
    Widget crumb(String label, int index, bool isCurrent) {
      final child = Padding(
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 8),
        child: Text(
          label,
          style: isCurrent
              ? style?.copyWith(fontWeight: FontWeight.bold)
              : style,
        ),
      );
      if (isCurrent) return child;
      return InkWell(
        borderRadius: BorderRadius.circular(4),
        onTap: () => _jumpTo(index),
        child: child,
      );
    }

    final crumbs = <Widget>[crumb('/', -1, _segments.isEmpty)];
    for (var i = 0; i < _segments.length; i++) {
      crumbs.add(Icon(Icons.chevron_right, size: 14, color: theme.hintColor));
      crumbs.add(crumb(_segments[i], i, i == _segments.length - 1));
    }
    return crumbs;
  }

  Widget _buildBody(BuildContext context) {
    final preview = _preview;
    if (preview != null) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              IconButton(
                icon: const Icon(Icons.arrow_back),
                tooltip: context.l10n.filesBackTooltip,
                onPressed: () => setState(() => _preview = null),
              ),
              Expanded(
                child: Text(
                  preview.name,
                  style: Theme.of(context).textTheme.titleSmall,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            ],
          ),
          const Divider(height: 1),
          Expanded(
            child: FilePreviewView(
              key: ValueKey('${preview.path}#$_previewRevision'),
              env: widget.env,
              path: preview.path,
              name: preview.name,
              htmlPreviewBuilder: widget.htmlPreviewBuilder,
            ),
          ),
        ],
      );
    }

    if (_loading) {
      return const Center(child: CircularProgressIndicator());
    }
    final error = _error;
    if (error != null) {
      final theme = Theme.of(context);
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.error_outline,
                size: 40,
                color: theme.colorScheme.error,
              ),
              const SizedBox(height: 12),
              Text(
                context.l10n.filesOpenFolderError,
                style: theme.textTheme.titleSmall,
              ),
              const SizedBox(height: 4),
              Text(
                error,
                style: theme.textTheme.bodySmall,
                textAlign: TextAlign.center,
              ),
              const SizedBox(height: 12),
              TextButton.icon(
                onPressed: _load,
                icon: const Icon(Icons.refresh, size: 18),
                label: Text(context.l10n.filesRetryButton),
              ),
            ],
          ),
        ),
      );
    }
    final entries = _entries!;
    if (entries.isEmpty) {
      final theme = Theme.of(context);
      return Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.folder_open_outlined, size: 40, color: theme.hintColor),
            const SizedBox(height: 12),
            Text(
              context.l10n.filesEmptyFolder,
              style: theme.textTheme.bodySmall,
            ),
          ],
        ),
      );
    }
    return ListView.builder(
      itemCount: entries.length,
      itemBuilder: (context, index) {
        final entry = entries[index];
        final isDir = entry.kind == FileKind.directory;
        return ListTile(
          dense: true,
          leading: Icon(_iconFor(entry), size: 20),
          title: Text(entry.name, overflow: TextOverflow.ellipsis),
          trailing: isDir
              ? const Icon(Icons.chevron_right, size: 18)
              : Text(
                  formatFileSize(entry.size),
                  style: Theme.of(context).textTheme.labelSmall,
                ),
          onTap: () => isDir ? _enterDir(entry) : _openFile(entry),
        );
      },
    );
  }
}

