import 'package:fa_ui/fa_ui.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart' show Clipboard, ClipboardData;

import 'package:fa/l10n/app_localizations.dart';
import 'package:fa/l10n/l10n_ext.dart';
import 'package:fa/network/fa_network_client.dart';
import 'package:fa/network/invite_codec.dart';
import 'package:fa/network/key_wallet.dart';
import 'package:fa/network/models.dart';
import 'package:fa/network/network_session_manager.dart';

/// What the invited agent gets access to (issue #955 steering): the ONE
/// channel (chankey E2E in the fragment) or the WHOLE network (join
/// link + password — a full member seeing every channel).
enum AgentInviteScope { channel, network }

/// The invite's consumer format: a bare link for desktop/mobile apps, a
/// ready CLI command for `fa`, env variables for the CLI harness on a CI
/// runner (GitHub Actions: paste straight into a step), or the pure-DAP
/// set for clients that know nothing about fa_network (a self-hosted DAP
/// hub + `fa dap`).
enum AgentInviteFormat { link, cli, env, dap }

/// The AC-B17 minimal agent pairing (issue #955): the agent invite
/// string for a channel or the whole network, as a link or a CLI
/// command. PRIVATE channels carry the keypair in the URI fragment —
/// `wss://<hub>?channel=<id>#pub=…&priv=…` (client-side only per RFC
/// 3986); PUBLIC channels have no chankey (showcase contract), so their
/// invite is the bare `wss://<hub>?channel=<id>`. The channel id is what
/// fa_network relays onto the DAP hub. The network scope shares the
/// human join link (`https://<host>/join?network=<id>#pw=…`). The string
/// never leaves the device except through the user's explicit Copy.
class AddAgentDialog extends StatefulWidget {
  const AddAgentDialog({
    super.key,
    required this.wallet,
    required this.manager,
    required this.networkId,
    required this.channel,
    this.initialScope = AgentInviteScope.channel,
  });

  /// The fa_network hub agents connect to. Placeholder constant until hubs
  /// become configurable — documented in issue #955.
  static const hubUrl = 'wss://hub.fa1.dev/ws';

  /// The web join-page origin for network-scope invites (the app parses
  /// `…/join?network=…` links itself). Same placeholder caveat.
  static const networkJoinHost = 'https://network.fa1.dev';

  /// The device wallet holding the channel keys and the network password.
  final KeyWallet wallet;

  /// The session manager — the DAP tab enrolls agents through it (the
  /// management JWT lives there; guests cannot enroll).
  final NetworkSessionManager manager;

  /// The network the channel belongs to.
  final String networkId;

  /// The channel the agent is invited into (channel scope). Null when the
  /// dialog is opened from the NETWORK header — the only scope then is
  /// the whole network (the scope switch is hidden).
  final Channel? channel;

  /// The scope the dialog opens on (channel scope by default).
  final AgentInviteScope initialScope;

  @override
  State<AddAgentDialog> createState() => _AddAgentDialogState();
}

class _AddAgentDialogState extends State<AddAgentDialog> {
  late AgentInviteScope _scope;
  AgentInviteFormat _format = AgentInviteFormat.link;

  /// The DAP tab's editable agent name (prefilled with the [_agentName]
  /// suggestion); enrollment mints a name-bound credential for it.
  late final TextEditingController _agentNameCtrl;

  /// The one-time credential returned by the enroll call (null until the
  /// user enrolls — the secret is shown ONCE, here and nowhere else).
  AgentEnrollment? _enrollment;

  /// The last enrollment failure's message (inline error under the row).
  String? _enrollError;

  /// True while the enroll request is in flight (the button disables).
  bool _enrolling = false;

  /// The deployed backend's agent-name rule (3–64 chars: lowercase,
  /// digits, hyphens; starts alnum).
  static final RegExp _agentNamePattern = RegExp(r'^[a-z0-9][a-z0-9-]{2,63}$');

  /// The env-var prefixes on the credential rows (consts so the l10n
  /// guard's literal scan stays quiet).
  static const hubUrlPrefix = 'DAP_HUB_URL=';
  static const clientSecretPrefix = 'DAP_CLIENT_SECRET=';
  static const agentNamePrefix = 'DAP_AGENT_NAME=';

  bool get _agentNameValid => _agentNamePattern.hasMatch(_agentNameCtrl.text);

  @override
  void initState() {
    super.initState();
    _scope = widget.channel == null
        ? AgentInviteScope.network
        : widget.initialScope;
    _agentNameCtrl = TextEditingController(text: _agentName);
  }

  @override
  void dispose() {
    _agentNameCtrl.dispose();
    super.dispose();
  }

  /// One monospace `key=value` line with its own copy button.
  Widget _envCopyRow(
    BuildContext context, {
    required String keyName,
    required String display,
    required String copyText,
  }) {
    final l10n = context.l10n;
    return Row(
      children: [
        Expanded(
          child: Text(
            display,
            key: ValueKey('envRow:$keyName'),
            style: const TextStyle(fontFamily: 'monospace', fontSize: 12),
          ),
        ),
        IconButton(
          key: ValueKey('envCopy:$keyName'),
          icon: const Icon(Icons.copy, size: 16),
          tooltip: l10n.networkCopy,
          visualDensity: VisualDensity.compact,
          onPressed: () async {
            await Clipboard.setData(ClipboardData(text: copyText));
            if (context.mounted) {
              showFahSnack(context, l10n.networkInviteCopied);
            }
          },
        ),
      ],
    );
  }

  /// The channel-scope invite string, or null when this device cannot
  /// produce one (private channel without keys in the wallet).
  String? get _channelInvite {
    final channel = widget.channel;
    if (channel == null) return null;
    if (channel.isPublic) {
      return buildPublicAgentInvite(
        hubUri: Uri.parse(AddAgentDialog.hubUrl),
        channel: channel.id,
      );
    }
    final keys = widget.wallet.channelKeysFor(widget.networkId, channel.id);
    if (keys == null) return null;
    return buildAgentInvite(
      hubUri: Uri.parse(AddAgentDialog.hubUrl),
      channel: channel.id,
      pub: keys.pub,
      priv: keys.priv,
    );
  }

  /// The network-scope chankey bundle: one invite per channel of the
  /// network the app knows about (the live session's channel list — the
  /// same source the channel rail uses). Private channels carry the
  /// chankey in the fragment when the wallet holds it; public channels
  /// get a keyless invite. Channels the wallet can produce no invite for
  /// are skipped — the invited agent sees those only after a key invite.
  List<(Channel, String)> get _channelInvites {
    final channels =
        widget.manager.sessions[widget.networkId]?.channels ??
        const <Channel>[];
    final hubUri = Uri.parse(AddAgentDialog.hubUrl);
    final invites = <(Channel, String)>[];
    for (final channel in channels) {
      if (channel.isPublic) {
        invites.add((
          channel,
          buildPublicAgentInvite(hubUri: hubUri, channel: channel.id),
        ));
        continue;
      }
      final keys = widget.wallet.channelKeysFor(widget.networkId, channel.id);
      if (keys == null) continue;
      invites.add((
        channel,
        buildAgentInvite(
          hubUri: hubUri,
          channel: channel.id,
          pub: keys.pub,
          priv: keys.priv,
        ),
      ));
    }
    return invites;
  }

  /// The network-scope join link. Always producible; the password rides
  /// the fragment when this device has it.
  String get _networkInvite {
    final entry = widget.wallet.networks[widget.networkId];
    return buildNetworkJoinLink(
      host: Uri.parse(AddAgentDialog.networkJoinHost),
      networkId: widget.networkId,
      password: entry?.password,
    );
  }

  /// The network password from the wallet (null when this device does
  /// not hold it). The env format splits it OUT of the URL so CI can
  /// keep the link a plain variable and the password a masked secret.
  String? get _networkPassword =>
      widget.wallet.networks[widget.networkId]?.password;

  /// The join link WITHOUT the password fragment — the CI-safe URL row.
  String get _networkUrlNoPassword => buildNetworkJoinLink(
    host: Uri.parse(AddAgentDialog.networkJoinHost),
    networkId: widget.networkId,
  );

  bool get _hasNetworkPassword => _networkPassword?.isNotEmpty ?? false;

  String? get _invite =>
      _scope == AgentInviteScope.channel ? _channelInvite : _networkInvite;

  /// What the user copies: the bare link, the CLI one-liner wrapping it
  /// (`fa dap import '…'`), or the env launch line for a CI runner. The
  /// link/CLI formats keep the canonical credential-in-fragment shape
  /// (the fragment never leaves the device over the wire); the ENV
  /// format splits the network password OUT into its own variable so CI
  /// can mask it as a secret while the URL stays a plain variable:
  /// `FA_NETWORK_URL='…' FA_NETWORK_PASSWORD='…' FA_AGENT_NAME=… fa` /
  /// `FA_CHANNEL_URL='…' FA_AGENT_NAME=… fa` (reserved for the CLI
  /// network mode). The DAP format is for pure-DAP clients that know
  /// nothing about fa_network: the DEPLOYED agent-enrollment backend
  /// mints a one-time, name-bound credential (`POST
  /// /api/networks/{id}/agents/enroll`, owner/admin only) — the payload
  /// is the DAP env launch line built from THAT response
  /// (`DAP_HUB_URL` / `DAP_CLIENT_SECRET` / `DAP_AGENT_NAME`). The hub
  /// master secret is banned from this UI: enrollment replaces it.
  String? get _payload {
    final invite = _invite;
    if (invite == null) return null;
    if (_format == AgentInviteFormat.link) return invite;
    if (_format == AgentInviteFormat.env) {
      if (_scope == AgentInviteScope.network) {
        final password = _hasNetworkPassword
            ? "FA_NETWORK_PASSWORD='$_networkPassword' "
            : '';
        final env =
            "FA_NETWORK_URL='$_networkUrlNoPassword' "
            '${password}FA_AGENT_NAME=$_agentName fa';
        // The chankey bundle rides as plain `fa dap import` commands —
        // a pure-DAP CI agent needs them today (the CLI network mode
        // will consume FA_NETWORK_URL later).
        final imports = [
          for (final (_, channelInvite) in _channelInvites)
            "fa dap import '$channelInvite'",
        ];
        return imports.isEmpty ? env : "${imports.join(' && ')} && $env";
      }
      return "FA_CHANNEL_URL='$invite' FA_AGENT_NAME=$_agentName fa";
    }
    if (_format == AgentInviteFormat.dap) {
      final enrollment = _enrollment;
      if (enrollment == null) return null;
      final imports = _scope == AgentInviteScope.channel
          ? ["fa dap import '$invite'"]
          : [
              for (final (_, channelInvite) in _channelInvites)
                "fa dap import '$channelInvite'",
            ];
      final import = imports.isEmpty ? '' : "${imports.join(' && ')} && ";
      return '$import$hubUrlPrefix${enrollment.hubUrl} '
          "$clientSecretPrefix'${enrollment.clientSecret}' "
          '$agentNamePrefix${enrollment.name} fa';
    }
    if (_scope == AgentInviteScope.network) return invite;
    return "fa dap import '$invite'";
  }

  /// Enrolls the typed agent name through the session manager (management
  /// route — owner/admin JWT required). The one-time credential lands in
  /// [_enrollment]; failures surface inline as [_enrollError].
  Future<void> _enroll() async {
    setState(() {
      _enrolling = true;
      _enrollError = null;
    });
    try {
      final enrollment = await widget.manager.enrollAgent(
        widget.networkId,
        _agentNameCtrl.text,
      );
      if (!mounted) return;
      setState(() => _enrollment = enrollment);
    } on FaNetworkException catch (e) {
      if (!mounted) return;
      setState(() => _enrollError = e.message);
    } on Object catch (e) {
      if (!mounted) return;
      setState(() => _enrollError = e.toString());
    } finally {
      if (mounted) setState(() => _enrolling = false);
    }
  }

  /// Suggested DAP_AGENT_NAME: a runner-friendly slug of the channel
  /// (plain `fa-agent` for the network scope).
  String get _agentName {
    final channel = widget.channel;
    if (_scope == AgentInviteScope.network || channel == null) {
      return 'fa-agent';
    }
    final name = channel.name ?? channel.id;
    final slug = name.toLowerCase().replaceAll(RegExp(r'[^a-z0-9]+'), '-');
    return '${slug.isEmpty ? 'channel' : slug}-agent';
  }

  @override
  Widget build(BuildContext context) {
    final colors = FahColors.of(context);
    final l10n = context.l10n;
    final payload = _payload;
    final isPublicChannel = widget.channel?.isPublic ?? false;
    return AlertDialog(
      title: Text(l10n.networkAddAgentTitle),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            _buildInviteHint(colors, l10n, isPublicChannel),
            const SizedBox(height: 12),
            if (widget.channel != null) ..._buildScopeSelector(l10n),
            _buildFormatSelector(l10n),
            ..._buildNoPasswordNote(colors, l10n),
            if (_format == AgentInviteFormat.env)
              ..._buildEnvRows(colors, l10n),
            if (_format == AgentInviteFormat.dap)
              ..._buildDapRows(colors, l10n),
            ..._buildCliHints(colors, l10n),
            const SizedBox(height: 12),
            _buildPayloadBox(colors, l10n, payload),
          ],
        ),
      ),
      actions: _buildActions(l10n, payload),
    );
  }

  /// The scope hint line: dim for the network scope and public channels,
  /// the error color for the private-channel warning.
  Widget _buildInviteHint(
    FahColors colors,
    AppLocalizations l10n,
    bool isPublicChannel,
  ) {
    return Text(
      _scope == AgentInviteScope.network
          ? l10n.networkAddAgentNetworkHint
          : isPublicChannel
          ? l10n.networkAddAgentPublicHint
          : l10n.networkAddAgentWarning,
      key: ValueKey(
        _scope == AgentInviteScope.network ? 'inviteScopeHint' : 'inviteHint',
      ),
      style: TextStyle(
        color: _inviteHintColor(colors, isPublicChannel),
        fontSize: 13,
      ),
    );
  }

  Color _inviteHintColor(FahColors colors, bool isPublicChannel) =>
      _scope == AgentInviteScope.network || isPublicChannel
      ? colors.dim
      : colors.error;

  List<Widget> _buildScopeSelector(AppLocalizations l10n) => [
    SegmentedButton<AgentInviteScope>(
      key: const ValueKey('inviteScope'),
      segments: [
        ButtonSegment(
          value: AgentInviteScope.channel,
          icon: const Icon(Icons.tag, size: 16),
          label: Text(l10n.networkAddAgentScopeChannel),
        ),
        ButtonSegment(
          value: AgentInviteScope.network,
          icon: const Icon(Icons.hub, size: 16),
          label: Text(l10n.networkAddAgentScopeNetwork),
        ),
      ],
      selected: {_scope},
      onSelectionChanged: (s) => setState(() => _scope = s.first),
    ),
    const SizedBox(height: 8),
  ];

  Widget _buildFormatSelector(AppLocalizations l10n) =>
      SegmentedButton<AgentInviteFormat>(
        key: const ValueKey('inviteFormat'),
        segments: [
          ButtonSegment(
            value: AgentInviteFormat.link,
            icon: const Icon(Icons.link, size: 16),
            label: Text(l10n.networkAddAgentFormatLink),
          ),
          ButtonSegment(
            value: AgentInviteFormat.cli,
            icon: const Icon(Icons.terminal, size: 16),
            label: Text(l10n.networkAddAgentFormatCli),
          ),
          ButtonSegment(
            value: AgentInviteFormat.env,
            icon: const Icon(Icons.settings_ethernet, size: 16),
            label: Text(l10n.networkAddAgentFormatEnv),
          ),
          ButtonSegment(
            value: AgentInviteFormat.dap,
            icon: const Icon(Icons.dns, size: 16),
            label: Text(l10n.networkAddAgentFormatDap),
          ),
        ],
        selected: {_format},
        onSelectionChanged: (s) => setState(() => _format = s.first),
      );

  List<Widget> _buildNoPasswordNote(FahColors colors, AppLocalizations l10n) =>
      [
        if (_scope == AgentInviteScope.network && !_hasNetworkPassword) ...[
          const SizedBox(height: 8),
          Text(
            l10n.networkAddAgentNetworkNoPassword,
            key: const ValueKey('inviteNoPassword'),
            style: TextStyle(color: colors.dim, fontSize: 12),
          ),
        ],
      ];

  List<Widget> _buildEnvRows(FahColors colors, AppLocalizations l10n) => [
    const SizedBox(height: 8),
    Text(
      l10n.networkAddAgentEnvHint,
      key: const ValueKey('inviteEnvHint'),
      style: TextStyle(color: colors.dim, fontSize: 12),
    ),
    const SizedBox(height: 8),
    // Per-variable rows with their own copy buttons — CI/CD
    // secrets/vars are pasted one key=value at a time. The
    // network password is its OWN row: the URL stays a plain
    // variable, the password goes into masked CI secrets.
    if (_scope == AgentInviteScope.network) ...[
      _envCopyRow(
        context,
        keyName: 'FA_NETWORK_URL',
        display: 'FA_NETWORK_URL=$_networkUrlNoPassword',
        copyText: 'FA_NETWORK_URL=$_networkUrlNoPassword',
      ),
      if (_hasNetworkPassword)
        _envCopyRow(
          context,
          keyName: 'FA_NETWORK_PASSWORD',
          display: 'FA_NETWORK_PASSWORD=$_networkPassword',
          copyText: 'FA_NETWORK_PASSWORD=$_networkPassword',
        ),
    ] else if (_invite != null)
      _envCopyRow(
        context,
        keyName: 'FA_CHANNEL_URL',
        display: 'FA_CHANNEL_URL=$_invite',
        copyText: 'FA_CHANNEL_URL=$_invite',
      ),
    _envCopyRow(
      context,
      keyName: 'FA_AGENT_NAME',
      display: 'FA_AGENT_NAME=$_agentName',
      copyText: 'FA_AGENT_NAME=$_agentName',
    ),
    // The network-scope chankey bundle: one import command per
    // channel this wallet can hand over (pure-DAP CI agents
    // need them today — the CLI network mode will consume
    // FA_NETWORK_URL later).
    if (_scope == AgentInviteScope.network) ..._envChannelImportRows(l10n),
  ];

  List<Widget> _envChannelImportRows(AppLocalizations l10n) => [
    for (final (channel, channelInvite) in _channelInvites)
      _envCopyRow(
        context,
        keyName: 'IMPORT:${channel.id}',
        display: "fa dap import '$channelInvite'",
        copyText: "fa dap import '$channelInvite'",
      ),
    if (_channelInvites.isEmpty)
      Text(
        l10n.networkAddAgentNoChannelKeys,
        key: const ValueKey('inviteNoChannelKeys'),
        style: TextStyle(color: FahColors.of(context).dim, fontSize: 12),
      ),
  ];

  List<Widget> _buildDapRows(FahColors colors, AppLocalizations l10n) => [
    const SizedBox(height: 8),
    Text(
      l10n.networkAddAgentEnrollHint,
      key: const ValueKey('inviteDapHint'),
      style: TextStyle(color: colors.dim, fontSize: 12),
    ),
    const SizedBox(height: 8),
    if (!widget.manager.hasJwt)
      Text(
        l10n.networkAddAgentEnrollNeedSignIn,
        key: const ValueKey('enrollNeedSignIn'),
        style: TextStyle(color: colors.error, fontSize: 13),
      )
    else ...[
      ..._enrollForm(colors, l10n),
      // The one-time credential panel — the secret is shown
      // here, once; re-enrolling the same name rotates it.
      if (_enrollment != null) ..._enrollmentRows(l10n),
    ],
  ];

  List<Widget> _enrollForm(FahColors colors, AppLocalizations l10n) => [
    Row(
      children: [
        Expanded(
          child: TextField(
            key: const ValueKey('agentNameField'),
            controller: _agentNameCtrl,
            onChanged: (_) => setState(() {}),
            style: const TextStyle(fontFamily: 'monospace', fontSize: 12),
            decoration: InputDecoration(
              isDense: true,
              errorText: _agentNameValid
                  ? null
                  : l10n.networkAddAgentNameInvalid,
            ),
          ),
        ),
        const SizedBox(width: 8),
        FilledButton(
          key: const ValueKey('enrollAgent'),
          onPressed: _agentNameValid && !_enrolling ? _enroll : null,
          child: Text(l10n.networkAddAgentEnroll),
        ),
      ],
    ),
    if (_enrollError != null) ...[
      const SizedBox(height: 8),
      Text(
        _enrollError!,
        key: const ValueKey('enrollError'),
        style: TextStyle(color: colors.error, fontSize: 12),
      ),
    ],
  ];

  List<Widget> _enrollmentRows(AppLocalizations l10n) => [
    const SizedBox(height: 8),
    if (_scope == AgentInviteScope.channel && _invite != null)
      _envCopyRow(
        context,
        keyName: 'IMPORT',
        display: "fa dap import '$_invite'",
        copyText: "fa dap import '$_invite'",
      ),
    _envCopyRow(
      context,
      keyName: 'DAP_HUB_URL',
      display: '$hubUrlPrefix${_enrollment!.hubUrl}',
      copyText: '$hubUrlPrefix${_enrollment!.hubUrl}',
    ),
    _envCopyRow(
      context,
      keyName: 'DAP_CLIENT_SECRET',
      display: '$clientSecretPrefix${_enrollment!.clientSecret}',
      copyText: '$clientSecretPrefix${_enrollment!.clientSecret}',
    ),
    _envCopyRow(
      context,
      keyName: 'DAP_AGENT_NAME',
      display: '$agentNamePrefix${_enrollment!.name}',
      copyText: '$agentNamePrefix${_enrollment!.name}',
    ),
    // The network scope: the identity alone cannot read or
    // post — hand over every channel invite this wallet can
    // produce, one IMPORT row per channel.
    if (_scope == AgentInviteScope.network) ..._enrollChannelImportRows(l10n),
  ];

  List<Widget> _enrollChannelImportRows(AppLocalizations l10n) => [
    for (final (channel, channelInvite) in _channelInvites)
      _envCopyRow(
        context,
        keyName: 'IMPORT:${channel.id}',
        display: "fa dap import '$channelInvite'",
        copyText: "fa dap import '$channelInvite'",
      ),
    if (_channelInvites.isEmpty) ...[
      const SizedBox(height: 4),
      Text(
        l10n.networkAddAgentNoChannelKeys,
        key: const ValueKey('inviteNoChannelKeys'),
        style: TextStyle(color: FahColors.of(context).dim, fontSize: 12),
      ),
    ],
  ];

  List<Widget> _buildCliHints(FahColors colors, AppLocalizations l10n) => [
    if (_format == AgentInviteFormat.cli &&
        _scope == AgentInviteScope.channel) ...[
      const SizedBox(height: 8),
      Text(
        l10n.networkAddAgentCliHint,
        key: const ValueKey('inviteCliHint'),
        style: TextStyle(color: colors.dim, fontSize: 12),
      ),
    ],
    if (_format == AgentInviteFormat.cli &&
        _scope == AgentInviteScope.network) ...[
      const SizedBox(height: 8),
      Text(
        l10n.networkAddAgentNetworkCliHint,
        key: const ValueKey('inviteNetworkCliHint'),
        style: TextStyle(color: colors.dim, fontSize: 12),
      ),
    ],
  ];

  Widget _buildPayloadBox(
    FahColors colors,
    AppLocalizations l10n,
    String? payload,
  ) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: colors.codeBg,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: colors.border),
      ),
      child: Text(
        payload ??
            (_format == AgentInviteFormat.dap
                // Pre-enrollment (or signed out): explain that
                // enrollment mints the unique, revocable
                // credential instead of showing a payload.
                ? l10n.networkAddAgentEnrollHint
                : l10n.networkAddAgentNoKeys),
        key: const ValueKey('agentInvite'),
        style: const TextStyle(fontFamily: 'monospace', fontSize: 12),
      ),
    );
  }

  List<Widget> _buildActions(AppLocalizations l10n, String? payload) => [
    TextButton(
      onPressed: () => Navigator.of(context).pop(),
      child: Text(l10n.networkClose),
    ),
    FilledButton.icon(
      key: const ValueKey('copyInvite'),
      onPressed: payload == null
          ? null
          : () async {
              await Clipboard.setData(ClipboardData(text: payload));
              if (context.mounted) {
                showFahSnack(context, l10n.networkInviteCopied);
              }
            },
      icon: const Icon(Icons.copy, size: 16),
      label: Text(l10n.networkCopy),
    ),
  ];
}

import 'package:fa/l10n/l10n_ext.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

import 'package:fa/ui/widgets/file_preview.dart';
import 'package:fa/services/icloud_sync_service.dart';
import 'package:fa/services/project_folder_channel.dart';
import 'package:fa/services/project_mount_env.dart';
import 'package:fa/services/project_mount_flow.dart';
import 'package:fa/services/upload.dart';
import 'package:fa/services/upload_picker_stub.dart'
    if (dart.library.html) 'package:fa/services/upload_picker_web.dart';
import 'package:fa_ui/fa_ui.dart' hide formatFileSize;

/// The default [ProjectFolderOps] on supported platforms (macOS), else null.
ProjectFolderOps? _defaultProjectFolderOps() =>
    ProjectFolderChannelOps.isSupported
    ? const ProjectFolderChannelOps()
    : null;

/// Width of the file browser panel (right side panel on wide layouts, end
/// drawer on narrow ones).
const double kFileBrowserPanelWidth = 300;

/// File browser over the agent's [ExecutionEnv].
///
/// Folders navigate (breadcrumb + up), files open a preview — inline in the
/// panel when [inlinePreview] is true (wide layouts), or as a pushed
/// [FilePreviewScreen] route otherwise (narrow layouts).
///
/// The header offers an upload button (when an [UploadPicker] is available,
/// i.e. on web or when one is injected) that writes picked files into the
/// currently viewed folder, so they land in the same sandbox filesystem the
/// agent's tools see.
///
/// When [fsRevision] is provided (see `AgentService.fsRevision`), every
/// bump refreshes the current directory listing and reloads the open
/// preview — that is how the browser learns the agent changed files,
/// without polling.
///
/// Typed against the [ExecutionEnv] abstraction only, so a cloud-backed env
/// can drop in later without UI changes. Navigation uses paths relative to
/// the env's working directory (never [FileInfo.path]): relative paths
/// resolve against the sandbox root on every backend, whereas returned
/// absolute paths are not portable across envs (e.g. the mobile sandbox maps
/// `/`-rooted paths onto a host directory).
class FileBrowser extends StatefulWidget {
  const FileBrowser({
    super.key,
    required this.env,
    this.inlinePreview = true,
    this.uploadPicker,
    this.iCloudSyncService,
    this.maxUploadBatchBytes = kMaxUploadBatchBytes,
    this.fsRevision,
    this.htmlPreviewBuilder,
    this.projectFolderOps,
    this.onProjectMountChanged,
  });

  /// The environment whose filesystem is browsed — the same instance the
  /// agent's tools use (see `AgentService.env`).
  final ExecutionEnv env;

  /// Whether file previews render inside the panel (true) or push a
  /// full-screen route (false).
  final bool inlinePreview;

  /// File chooser behind the upload button. Defaults to the platform picker
  /// (`null` off the web → the button is hidden); tests inject a fake.
  final UploadPicker? uploadPicker;

  /// iCloud sync backend behind the header's sync button. Defaults to the
  /// platform service (`null` off macOS/iOS → the button is hidden); tests
  /// inject a fake (same pattern as [uploadPicker]).
  final ICloudSyncService? iCloudSyncService;

  /// Total-byte cap for one upload batch; oversized batches are refused
  /// with a message before anything is written.
  final int maxUploadBatchBytes;

  /// Agent filesystem revision: every bump reloads the listing and the open
  /// preview. `null` disables auto-refresh (manual refresh still works).
  final ValueListenable<int>? fsRevision;

  /// Override for the HTML rendering surface; tests inject a fake because
  /// the webview plugin has no platform implementation on the host.
  final HtmlPreviewBuilder? htmlPreviewBuilder;

  /// Native project-folder operations behind the open-folder control
  /// (macOS sandbox flow); defaults to the channel ops when supported.
  /// Tests inject a fake.
  final ProjectFolderOps? projectFolderOps;

  /// Fired after the project-folder mount changes (mount/unmount), so the
  /// host can recompose the agent's system prompt.
  final void Function()? onProjectMountChanged;

  @override
  State<FileBrowser> createState() => _FileBrowserState();
}

class _FileBrowserState extends State<FileBrowser> {
  /// Current directory as segments relative to the env root (`[]` = root).
  final List<String> _segments = [];

  List<FileInfo>? _entries;
  String? _error;

  /// The mount env when the agent's env is one (desktop/macOS); null
  /// elsewhere (the open-folder control hides then). Looks through the
  /// [SecretsExecutionEnv] wrapper the agent service always puts around
  /// the shared env.
  ProjectMountEnv? get _mountEnv {
    var env = widget.env;
    if (env is SecretsExecutionEnv) env = env.delegate;
    return env is ProjectMountEnv ? env : null;
  }

  Future<void> _pickProjectFolder() async {
    final ops = widget.projectFolderOps ?? _defaultProjectFolderOps();
    final String? picked;
    try {
      picked = await pickAndApplyProjectMount(
        env: widget.env,
        ops: ops,
        onApplied: () => widget.onProjectMountChanged?.call(),
        onAccessDenied: () {
          if (mounted) {
            showFahErrorSnack(context, context.l10n.filesFolderAccessDenied);
          }
        },
      );
    } on Object catch (e) {
      if (mounted) {
        showFahErrorSnack(
          context,
          context.l10n.filesFolderPickerError(e.toString()),
        );
      }
      return;
    }
    if (picked == null) return;
    setState(() {});
    await _load();
  }

  Future<void> _unmountProjectFolder() async {
    final cleared = await unapplyProjectMount(
      env: widget.env,
      ops: widget.projectFolderOps ?? _defaultProjectFolderOps(),
      onApplied: () => widget.onProjectMountChanged?.call(),
    );
    if (!cleared) return;
    setState(() {});
    await _load();
  }

  bool _loading = true;

  /// Inline preview target, when [FileBrowser.inlinePreview] is on.
  ({String path, String name})? _preview;

  /// Counter folded into the inline preview's key: bumping it forces the
  /// preview to re-read its file (agent-side mutation hook).
  int _previewRevision = 0;

  /// Resolved picker: the injected one, else the platform default (`null`
  /// off the web, which hides the upload button).
  late final UploadPicker? _picker =
      widget.uploadPicker ?? createUploadPicker();

  /// iCloud sync backend behind the header's sync button; `null` off
  /// macOS/iOS (web/Android), which hides the button. Manual trigger only.
  late final ICloudSyncService? _iCloudSync =
      widget.iCloudSyncService ??
      (icloudSyncSupported ? createICloudSyncService(widget.env) : null);

  @override
  void initState() {
    super.initState();
    widget.fsRevision?.addListener(_onFsRevision);
    _load();
  }

  @override
  void didUpdateWidget(FileBrowser oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.fsRevision != widget.fsRevision) {
      oldWidget.fsRevision?.removeListener(_onFsRevision);
      widget.fsRevision?.addListener(_onFsRevision);
    }
  }

  @override
  void dispose() {
    widget.fsRevision?.removeListener(_onFsRevision);
    super.dispose();
  }

  /// Agent-side filesystem change ("hook"): reload the listing and force
  /// the open preview to re-read its file. Conservative — a bump does not
  /// say which file changed (`bash` can touch anything), and one extra
  /// listDir/read is cheap.
  void _onFsRevision() {
    if (_preview != null) _previewRevision++;
    _load();
  }

  /// Path of the current directory in the env namespace, relative to its
  /// working directory.
  String get _envPath => _segments.isEmpty ? '.' : _segments.join('/');

  String _childPath(String name) =>
      _segments.isEmpty ? name : '${_segments.join('/')}/$name';

  Future<void> _load() async {
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final result = await widget.env.listDir(_envPath);
      if (!mounted) return;
      final entries = result.valueOrNull;
      if (entries == null) {
        setState(() {
          _entries = null;
          _loading = false;
          _error =
              result.errorOrNull?.message ?? context.l10n.filesListFolderError;
        });
        return;
      }
      int byName(FileInfo a, FileInfo b) =>
          a.name.toLowerCase().compareTo(b.name.toLowerCase());
      final dirs = entries.where((e) => e.kind == FileKind.directory).toList()
        ..sort(byName);
      final files = entries.where((e) => e.kind != FileKind.directory).toList()
        ..sort(byName);
      setState(() {
        _entries = [...dirs, ...files];
        _loading = false;
      });
    } on Object catch (e) {
      // Defensive: FileSystem operations are contract-bound to return Err
      // instead of throwing; keep the UI alive if a backend misbehaves.
      if (!mounted) return;
      setState(() {
        _entries = null;
        _loading = false;
        _error = e.toString();
      });
    }
  }

  void _enterDir(FileInfo info) {
    setState(() {
      _segments.add(info.name);
      _preview = null;
    });
    _load();
  }

  void _goUp() {
    if (_segments.isEmpty) return;
    setState(() {
      _segments.removeLast();
      _preview = null;
    });
    _load();
  }

  /// Jumps to the breadcrumb at [index] (-1 = root).
  void _jumpTo(int index) {
    setState(() {
      _segments.removeRange(index + 1, _segments.length);
      _preview = null;
    });
    _load();
  }

  void _openFile(FileInfo info) {
    final path = _childPath(info.name);
    if (widget.inlinePreview) {
      setState(() => _preview = (path: path, name: info.name));
    } else {
      Navigator.of(context).push(
        MaterialPageRoute<void>(
          builder: (_) => FilePreviewScreen(
            env: widget.env,
            path: path,
            name: info.name,
            htmlPreviewBuilder: widget.htmlPreviewBuilder,
            fsRevision: widget.fsRevision,
          ),
        ),
      );
    }
  }

  void _showSnack(String message, {bool error = false}) {
    error
        ? showFahErrorSnack(
            context,
            message,
            duration: const Duration(seconds: 3),
            hideCurrent: true,
          )
        : showFahSnack(context, message, duration: const Duration(seconds: 3));
  }

  /// Runs one iCloud merge of the sandbox sessions/apps trees and reports
  /// the outcome as a snackbar (synced counts, or the unavailable guidance
  /// when the ubiquity container is missing).
  Future<void> _syncICloud() async {
    final service = _iCloudSync;
    if (service == null) return;
    await _runSync(service);
  }

  /// Guarded sync body: availability check, one merge, then the outcome
  /// snackbar + reload (extracted so [_syncICloud] stays a thin guard).
  Future<void> _runSync(ICloudSyncService service) async {
    if (!await service.isAvailable()) {
      if (mounted) _showSyncUnavailable();
      return;
    }
    try {
      final report = await service.syncNow();
      if (!mounted) return;
      _showSyncDone(report);
      await _load();
    } on Object catch (e) {
      if (mounted) _showSyncFailed(e);
    }
  }

  void _showSyncUnavailable() =>
      _showSnack(context.l10n.filesICloudSyncUnavailable, error: true);

  void _showSyncDone(ICloudSyncReport report) => _showSnack(
    context.l10n.filesICloudSyncDone(
      report.filesCopied,
      formatFileSize(report.bytesCopied),
      formatICloudSyncTimestamp(report.syncedAt),
    ),
  );

  void _showSyncFailed(Object e) =>
      _showSnack(context.l10n.filesICloudSyncFailed(e.toString()), error: true);

  /// Picks files and writes them into the currently viewed folder of the
  /// sandbox filesystem, so the agent can work with them right away.
  Future<void> _upload() async {
    final picker = _picker;
    if (picker == null) return;
    final picked = await _pickUploadFiles(picker);
    if (picked == null || picked.isEmpty || !mounted) return;
    final sizeError = uploadBatchSizeError(
      picked,
      maxBytes: widget.maxUploadBatchBytes,
      message: (total, max) => context.l10n.uploadTooLarge(max, total),
    );
    if (sizeError != null) {
      _showSnack(sizeError, error: true);
      return;
    }
    await _writeUploadedFiles(picked);
  }

  /// The picked files; null when the picker failed (error snack shown).
  Future<List<UploadFile>?> _pickUploadFiles(UploadPicker picker) async {
    final List<UploadFile> picked;
    try {
      picked = await picker.pick();
    } on Object catch (e) {
      if (mounted) {
        _showSnack(context.l10n.filesUploadFailed(e.toString()), error: true);
      }
      return null;
    }
    return picked;
  }

  Future<void> _writeUploadedFiles(List<UploadFile> picked) async {
    final (written, failed) = await _writeUploadBatch(picked);
    if (!mounted) return;
    if (written > 0) await _load();
    if (!mounted) return;
    _showUploadSummary(written, failed);
  }

  Future<(int, List<String>)> _writeUploadBatch(List<UploadFile> picked) async {
    var written = 0;
    final failed = <String>[];
    final emptyName = context.l10n.filesEmptyFileName;
    for (final file in picked) {
      final name = sanitizeUploadName(file.name);
      if (name.isEmpty) {
        failed.add(file.name.isEmpty ? emptyName : file.name);
        continue;
      }
      final result = await widget.env.writeBinaryFile(
        _childPath(name),
        file.bytes,
      );
      if (result.isOk) {
        written++;
      } else {
        failed.add(name);
      }
    }
    return (written, failed);
  }

  /// Failures stay visible: which files, not just how many.
  void _showUploadSummary(int written, List<String> failed) {
    final failures = failed.isNotEmpty
        ? context.l10n.filesUploadFailures(
            failed.length.toString(),
            failed.join(', '),
          )
        : '';
    _showSnack(context.l10n.filesUploadSummary(failures, written));
  }

  IconData _iconFor(FileInfo info) {
    if (info.kind == FileKind.directory) return Icons.folder_outlined;
    return switch (fileExtension(info.name)) {
      '.png' || '.jpg' || '.jpeg' || '.gif' || '.webp' => Icons.image_outlined,
      _ => Icons.insert_drive_file_outlined,
    };
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _buildHeader(context),
        _buildPathBar(context),
        const Divider(height: 1),
        Expanded(child: _buildBody(context)),
      ],
    );
  }

  Widget _buildHeader(BuildContext context) {
    final theme = Theme.of(context);
    return Padding(
      padding: const EdgeInsets.fromLTRB(16, 12, 4, 0),
      child: Row(
        children: [
          Icon(Icons.folder_open_outlined, size: 20, color: theme.hintColor),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              context.l10n.filesPanelTitle,
              style: theme.textTheme.titleMedium,
            ),
          ),
          ?_buildMountControl(context),
          if (_picker != null)
            IconButton(
              icon: const Icon(Icons.upload_file),
              tooltip: context.l10n.filesUploadTooltip,
              onPressed: _upload,
            ),
          if (_iCloudSync != null)
            IconButton(
              icon: const Icon(Icons.cloud_sync_outlined),
              tooltip: context.l10n.filesICloudSyncTooltip,
              onPressed: _syncICloud,
            ),
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: context.l10n.filesRefreshTooltip,
            onPressed: _load,
          ),
        ],
      ),
    );
  }

  /// The project-folder control for the header (macOS sandbox): an
  /// open-folder button when unmounted, a name+eject chip when mounted, a
  /// warning chip when the stored folder became unavailable. Null when the
  /// env has no mount support (web/mobile).
  Widget? _buildMountControl(BuildContext context) {
    final mountEnv = _mountEnv;
    if (mountEnv == null) return null;
    final unavailable = mountEnv.mountUnavailable;
    if (unavailable != null) {
      return IconButton(
        icon: Icon(
          Icons.warning_amber_outlined,
          color: Theme.of(context).colorScheme.error,
        ),
        tooltip: context.l10n.filesMountUnavailableTooltip(unavailable),
        onPressed: _pickProjectFolder,
      );
    }
    final mountedPath = mountEnv.mountedRoot;
    if (mountedPath != null) {
      final name = mountedPath.split('/').where((part) => part.isNotEmpty).last;
      return Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(name, style: Theme.of(context).textTheme.bodySmall),
          IconButton(
            icon: const Icon(Icons.eject_outlined),
            tooltip: context.l10n.filesUnmountTooltip(mountedPath),
            onPressed: _unmountProjectFolder,
          ),
        ],
      );
    }
    final canPick =
        widget.projectFolderOps != null || ProjectFolderChannelOps.isSupported;
    if (!canPick) return null;
    return IconButton(
      icon: const Icon(Icons.create_new_folder_outlined),
      tooltip: context.l10n.filesOpenProjectFolderTooltip,
      onPressed: _pickProjectFolder,
    );
  }

  Widget _buildPathBar(BuildContext context) {
    return SizedBox(
      height: 44,
      child: Row(
        children: [
          IconButton(
            icon: const Icon(Icons.arrow_upward, size: 18),
            tooltip: context.l10n.filesUpTooltip,
            onPressed: _segments.isEmpty ? null : _goUp,
          ),
          Expanded(
            child: SingleChildScrollView(
              scrollDirection: Axis.horizontal,
              child: Row(children: _breadcrumbs(context)),
            ),
          ),
        ],
      ),
    );
  }

  List<Widget> _breadcrumbs(BuildContext context) {
    final theme = Theme.of(context);
    final style = theme.textTheme.bodySmall;
    Widget crumb(String label, int index, bool isCurrent) {
      final child = Padding(
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 8),
        child: Text(
          label,
          style: isCurrent
              ? style?.copyWith(fontWeight: FontWeight.bold)
              : style,
        ),
      );
      if (isCurrent) return child;
      return InkWell(
        borderRadius: BorderRadius.circular(4),
        onTap: () => _jumpTo(index),
        child: child,
      );
    }

    final crumbs = <Widget>[crumb('/', -1, _segments.isEmpty)];
    for (var i = 0; i < _segments.length; i++) {
      crumbs.add(Icon(Icons.chevron_right, size: 14, color: theme.hintColor));
      crumbs.add(crumb(_segments[i], i, i == _segments.length - 1));
    }
    return crumbs;
  }

  Widget _buildBody(BuildContext context) {
    final preview = _preview;
    if (preview != null) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              IconButton(
                icon: const Icon(Icons.arrow_back),
                tooltip: context.l10n.filesBackTooltip,
                onPressed: () => setState(() => _preview = null),
              ),
              Expanded(
                child: Text(
                  preview.name,
                  style: Theme.of(context).textTheme.titleSmall,
                  overflow: TextOverflow.ellipsis,
                ),
              ),
            ],
          ),
          const Divider(height: 1),
          Expanded(
            child: FilePreviewView(
              key: ValueKey('${preview.path}#$_previewRevision'),
              env: widget.env,
              path: preview.path,
              name: preview.name,
              htmlPreviewBuilder: widget.htmlPreviewBuilder,
            ),
          ),
        ],
      );
    }

    if (_loading) {
      return const Center(child: CircularProgressIndicator());
    }
    final error = _error;
    if (error != null) {
      final theme = Theme.of(context);
      return Center(
        child: Padding(
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.error_outline,
                size: 40,
                color: theme.colorScheme.error,
              ),
              const SizedBox(height: 12),
              Text(
                context.l10n.filesOpenFolderError,
                style: theme.textTheme.titleSmall,
              ),
              const SizedBox(height: 4),
              Text(
                error,
                style: theme.textTheme.bodySmall,
                textAlign: TextAlign.center,
              ),
              const SizedBox(height: 12),
              TextButton.icon(
                onPressed: _load,
                icon: const Icon(Icons.refresh, size: 18),
                label: Text(context.l10n.filesRetryButton),
              ),
            ],
          ),
        ),
      );
    }
    final entries = _entries!;
    if (entries.isEmpty) {
      final theme = Theme.of(context);
      return Center(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.folder_open_outlined, size: 40, color: theme.hintColor),
            const SizedBox(height: 12),
            Text(
              context.l10n.filesEmptyFolder,
              style: theme.textTheme.bodySmall,
            ),
          ],
        ),
      );
    }
    return ListView.builder(
      itemCount: entries.length,
      itemBuilder: (context, index) {
        final entry = entries[index];
        final isDir = entry.kind == FileKind.directory;
        return ListTile(
          dense: true,
          leading: Icon(_iconFor(entry), size: 20),
          title: Text(entry.name, overflow: TextOverflow.ellipsis),
          trailing: isDir
              ? const Icon(Icons.chevron_right, size: 18)
              : Text(
                  formatFileSize(entry.size),
                  style: Theme.of(context).textTheme.labelSmall,
                ),
          onTap: () => isDir ? _enterDir(entry) : _openFile(entry),
        );
      },
    );
  }
}

