// l10n:ignore-file — prototype redesign ships en-only copy for now
// (the "Load unpacked" button below is the one deliberate exception: the
// key already exists for the launcher row, so it is reused).
import 'dart:async';

import 'package:fa/apps/app_icon.dart';
import 'package:fa/apps/app_load_error.dart';
import 'package:fa/apps/apps_store.dart';
import 'package:fa/apps/unpacked_load_flow.dart';
import 'package:fa/apps/widgets_catalog_sheet.dart';
import 'package:fa/apps/js_app_navigation.dart';
import 'package:fa/l10n/l10n_ext.dart';
import 'package:fa/services/agent_service.dart';
import 'package:fa/services/analytics.dart';
import 'package:fa/services/calendar_service.dart';
import 'package:fa/services/flutter_session_manager.dart';
import 'package:fa/services/folder_picker.dart';
import 'package:fa/services/widget_publication_store.dart';
import 'package:fa/services/widget_publish_service.dart';
import 'package:fa/ui/widgets/github_account_section.dart';
import 'package:fa/ui/widgets/widget_publish_sheet.dart';
import 'package:fa_ui/fa_ui.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

/// The right-side "My Apps" panel for the [WideLayoutShell].
///
/// Structured like the prototype: a header with count, a search bar,
/// filter chips (All/Recent/Created/Pinned), optional weather/timer widget,
/// then a 4-column grid of app tiles grouped into sections, and a
/// "Recent activity" footer.
class AppsPanel extends StatefulWidget {
  const AppsPanel({
    super.key,
    required this.manager,
    this.appsStore,
    this.sessionNamesStore,
    this.registry,
  });

  final FlutterSessionManager manager;

  /// App discovery/seeding; null → creates one from the manager's env.
  final AppsStore? appsStore;

  final dynamic sessionNamesStore;

  /// Custom-provider registry — forwarded to [SettingsScreen] when an
  /// app tap lands without an active service (post-onboarding
  /// empty-manager home), so the "Add provider" path from there has
  /// the same registry instance.
  final ProviderRegistry? registry;

  @override
  State<AppsPanel> createState() => _AppsPanelState();
}

class _AppsPanelState extends State<AppsPanel> {
  final _searchController = TextEditingController();
  late final AppsStore _appsStore;
  List<JsAppInfo> _apps = const [];
  var _loading = true;
  var _filter = _AppFilter.all;

  /// Whether we're on macOS desktop (traffic lights float over content).
  static bool get _isMacOS =>
      !kIsWeb && defaultTargetPlatform == TargetPlatform.macOS;

  @override
  void initState() {
    super.initState();
    _appsStore = widget.appsStore ?? AppsStore(widget.manager.env);
    _searchController.addListener(_onSearchChanged);
    _reloadApps();
    unawaited(_loadCalendar());
    widget.manager.active?.service.fsRevision.addListener(_onFsRevision);
  }

  @override
  void dispose() {
    widget.manager.active?.service.fsRevision.removeListener(_onFsRevision);
    _searchController.removeListener(_onSearchChanged);
    _searchController.dispose();
    super.dispose();
  }

  void _onSearchChanged() {
    if (mounted) setState(() {});
  }

  void _onFsRevision() {
    if (mounted) _reloadApps();
  }

  Future<void> _reloadApps() async {
    try {
      final apps = await _appsStore.listApps();
      if (mounted) {
        setState(() {
          _apps = apps;
          _loading = false;
        });
      }
    } on Object {
      if (mounted) setState(() => _loading = false);
    }
  }

  /// Today's remaining calendar events for the "Up next" widget.
  List<CalendarEvent> _upcomingEvents = const [];
  var _calendarLoaded = false;

  Future<void> _loadCalendar() async {
    try {
      await _refreshUpcomingEvents();
    } on Object {
      if (mounted) setState(() => _calendarLoaded = true);
    }
  }

  /// Fetches today's remaining events into [_upcomingEvents]; an
  /// unavailable service marks the widget loaded with nothing scheduled.
  Future<void> _refreshUpcomingEvents() async {
    final calendar = createCalendarService();
    if (!await _calendarReady(calendar)) return;
    await _fetchUpcomingEvents(calendar);
  }

  /// Marks the widget loaded when the calendar service is unavailable —
  /// the "Up next" tile just stays empty.
  Future<bool> _calendarReady(calendar) async {
    if (await calendar.isAvailable) return true;
    if (mounted) setState(() => _calendarLoaded = true);
    return false;
  }

  Future<void> _fetchUpcomingEvents(calendar) async {
    final now = DateTime.now();
    final endOfDay = DateTime(now.year, now.month, now.day, 23, 59, 59);
    final events = await calendar.events(start: now, end: endOfDay);
    if (mounted) {
      setState(() {
        _upcomingEvents = events.take(3).toList();
        _calendarLoaded = true;
      });
    }
  }

  List<JsAppInfo> get _demoApps => _apps.where((a) => a.bundled).toList();
  List<JsAppInfo> get _customApps => _apps.where((a) => !a.bundled).toList();

  List<JsAppInfo> get _filteredApps {
    final query = _searchController.text.trim().toLowerCase();
    final source = switch (_filter) {
      _AppFilter.all => _apps,
      _AppFilter.recent => _apps,
      _AppFilter.created => _customApps,
      _AppFilter.pinned => _apps,
    };
    if (query.isEmpty) return source.toList();
    return source
        .where(
          (a) =>
              a.name.toLowerCase().contains(query) ||
              a.id.toLowerCase().contains(query) ||
              a.description.toLowerCase().contains(query),
        )
        .toList();
  }

  Future<void> _openApp(JsAppInfo app) async {
    // Broken-app guard — the panel is the surface #866 is named after; a
    // broken app shows the copyable dialog, never a silent launch.
    if (await guardBrokenApp(context, app)) return;
    if (!mounted) return;
    final manager = widget.manager;
    // The post-onboarding empty-manager home always has a placeholder
    // session (see _buildHomeWithEmptyManager), so an active service
    // exists even before the user wires up a provider. Apps that need
    // LLM will fail gracefully inside the app; the rest (calendar,
    // notes, weather, etc.) work without one.
    AppAnalytics.instance.jsAppOpened(
      isDemo: AppsStore.demoAppIds.contains(app.id),
      source: 'apps_panel',
    );
    pushJsApp(context, manager: manager, app: app, source: 'apps_panel');
  }

  /// The widgets-catalog bottom sheet over the shared env (install /
  /// update catalog widgets — see [WidgetsCatalogSheet]).
  Future<void> _openWidgetsCatalog() async {
    AppAnalytics.instance.widgetEvent('gallery_open', params: const {});
    await showWidgetsCatalogSheet(
      context,
      env: widget.manager.env,
      manager: widget.manager,
    );
  }

  /// Opens the publish sheet for a user widget (issue #35), backed by the
  /// app sandbox env and the shared GitHub account store.
  Future<void> _publishApp(JsAppInfo app) async {
    final keys = SessionKeysScope.maybeOf(context);
    final account = sharedGithubAccountStore(
      keys ?? await SessionKeysStore.load(widget.manager.env),
    );
    final ledger = await initSharedWidgetPublicationStore(widget.manager.env);
    final service = WidgetPublishService(
      env: widget.manager.env,
      account: account,
      ledger: ledger,
    );
    if (!mounted) return;
    await showWidgetPublishSheet(
      context,
      app: app,
      account: account,
      service: service,
      ledger: ledger,
    );
  }

  /// Long-press on a grid tile: Open always; Remove for non-bundled apps
  /// (catalog downloads AND agent-created apps — `force` covers apps that
  /// are not recorded in `.installed.json`). `storage.json` always stays.
  Future<void> _showAppMenu(JsAppInfo app, Offset globalPosition) async {
    final overlay = Overlay.of(context).context.findRenderObject();
    if (overlay is! RenderBox) return;
    final selected = await showMenu<String>(
      context: context,
      position: RelativeRect.fromRect(
        globalPosition & const Size(1, 1),
        Offset.zero & overlay.size,
      ),
      items: [
        const PopupMenuItem<String>(value: 'open', child: Text('Open')),
        if (!app.bundled)
          const PopupMenuItem<String>(
            value: 'publish',
            child: Text('Publish…'),
          ),
        if (!app.bundled)
          const PopupMenuItem<String>(
            value: 'remove',
            child: Text('Remove widget'),
          ),
      ],
    );
    if (selected == 'open') {
      unawaited(_openApp(app));
      return;
    }
    if (selected == 'publish') {
      await _publishApp(app);
      return;
    }
    if (selected != 'remove' || !mounted) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: Text('Remove ${app.name}?'),
        content: const Text(
          'The widget files are deleted; its saved data (storage.json) '
          'is kept, so reinstalling restores its state.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(false),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(true),
            child: const Text('Remove'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    AppAnalytics.instance.widgetEvent('remove', params: {'id': app.id});
    final removed = await _appsStore.removeWidget(app.id, force: true);
    if (!mounted) return;
    if (removed) {
      await _reloadApps();
    } else {
      showFahErrorSnack(context, 'Could not remove ${app.name}.');
    }
  }

  /// A blank request or no active agent service — nothing to ask Fa
  /// (gh-1848 split).
  static bool _isBlankWidgetRequest(String? text, AgentService? service) =>
      text == null || text.isEmpty || service == null;

  /// "Add widget" tile: the user describes what they want; Fa checks the
  /// catalog for a match (offers to install) or proposes a creation plan.
  Future<void> _showAddWidgetDialog() async {
    final service = widget.manager.active?.service;
    final controller = TextEditingController();
    final request = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Add widget'),
        content: TextField(
          controller: controller,
          autofocus: true,
          maxLines: 3,
          minLines: 1,
          decoration: const InputDecoration(
            hintText: 'Describe the widget you want…',
          ),
          onSubmitted: (value) => Navigator.of(dialogContext).pop(value),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(dialogContext).pop(),
            child: const Text('Cancel'),
          ),
          FilledButton(
            onPressed: () => Navigator.of(dialogContext).pop(controller.text),
            child: const Text('Ask Fa'),
          ),
        ],
      ),
    );
    final text = request?.trim();
    if (_isBlankWidgetRequest(text, service)) return;
    AppAnalytics.instance.widgetEvent('add_widget_request', params: const {});
    // The blank/absent-service guard above proves `service` non-null; the
    // predicate form just defeats promotion.
    await service!.sendText(
      'The user wants a new widget: "$text".\n'
      '1. First check the fa_widgets catalog (apps_catalog tool, action '
      '"list") — if a widget already matches this request, tell the user '
      'which one and ask for confirmation, then install it (action '
      '"install").\n'
      '2. If nothing matches, propose a short plan to CREATE the widget '
      'as a JS app under apps/ (follow the js-apps skill), and ask the '
      'user before writing any code.',
    );
  }

