  Widget _buildContent(FahColors colors, ThemeData theme, bool isLight) {
    final filtered = _filteredApps;
    final query = _searchController.text.trim();

    if (query.isNotEmpty) {
      // Search mode: flat grid of matches.
      return GridView.builder(
        padding: const EdgeInsets.all(12),
        gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
          crossAxisCount: 4,
          childAspectRatio: 0.82,
          crossAxisSpacing: 8,
          mainAxisSpacing: 12,
        ),
        itemCount: filtered.length,
        itemBuilder: (context, index) => _AppTile(
          app: filtered[index],
          onTap: () => _openApp(filtered[index]),
          onLongPress: (position) => _showAppMenu(filtered[index], position),
        ),
      );
    }

    // Sectioned view matching the prototype. The "Weather placeholder"
    // and "System tiles" rows used to live here as grey stub icons
    // (Calendar, Files, Notes, Maps, Calculator, Settings, Utilities,
    // Travel); they were placeholders that opened nothing or a blank
    // Scaffold. Calendar / Weather / Contacts / Reminders / Health /
    // Maps live in the bundled apps (see AppsStore.demoAppIds) and
    // surface as real tiles under Demo apps below — there's nothing to
    // "stub" here. Focus Timer + Up next are real interactive widgets.
    return ListView(
      padding: const EdgeInsets.all(12),
      children: [
        // ── Up next (real calendar events) ───────────────────────
        if (_calendarLoaded && _upcomingEvents.isNotEmpty) ...[
          _UpNextWidget(
            colors: colors,
            theme: theme,
            isLight: isLight,
            events: _upcomingEvents,
          ),
          const SizedBox(height: 12),
        ],
        // ── Focus Timer (real interactive 25-min pomodoro) ───────
        _FocusTimerWidget(colors: colors, theme: theme, isLight: isLight),
        const SizedBox(height: 8),
        // Always-visible entry to the widgets catalog: installs sample
        // widgets from the fa_widgets release (see WidgetsCatalogSheet).
        // Lives OUTSIDE the demo section on purpose — an install with no
        // demo apps (or an old one that already seeded them) must still
        // see the gallery.
        Row(
          children: [
            const Spacer(),
            TextButton.icon(
              onPressed: _openWidgetsCatalog,
              icon: const Icon(Icons.widgets_outlined, size: 18),
              label: const Text('Get widgets'),
            ),
            // gh-1616: Chrome-parity "Load unpacked" — a local
            // apps/<id>/ folder loads, validates and persists like a
            // catalog install. Hidden on hosts with no folder picker.
            if (createFolderPicker() != null)
              TextButton.icon(
                onPressed: () => loadUnpackedWidget(
                  context,
                  manager: widget.manager,
                  appsStore: _appsStore,
                ),
                icon: const Icon(Icons.folder_open, size: 18),
                label: Text(context.l10n.launcherLoadUnpacked),
              ),
          ],
        ),
        const SizedBox(height: 8),

        // ── Custom apps section ──────────────────────────────────
        if (_customApps.isNotEmpty) ...[
          _SectionHeader(title: 'My widgets', count: _customApps.length),
          const SizedBox(height: 8),
          _AppGrid(
            apps: _customApps,
            onTap: _openApp,
            onLongPress: _showAppMenu,
            showAddTile: true,
            onAdd: _showAddWidgetDialog,
          ),
          const SizedBox(height: 16),
        ],

        // ── Demo apps section ────────────────────────────────────
        if (_demoApps.isNotEmpty) ...[
          _SectionHeader(title: 'Demo apps', count: _demoApps.length),
          const SizedBox(height: 8),
          _AppGrid(apps: _demoApps, onTap: _openApp, onLongPress: _showAppMenu),
          const SizedBox(height: 8),
        ],

        // ── All apps fallback ────────────────────────────────────
        if (_customApps.isEmpty && _demoApps.isEmpty)
          Center(
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Text(
                'No apps yet.\nAsk Fa to build one!',
                textAlign: TextAlign.center,
                style: theme.textTheme.bodySmall?.copyWith(color: colors.dim),
              ),
            ),
          ),

        // ── Recent activity ──────────────────────────────────────
        const Divider(height: 1),
        const SizedBox(height: 8),
        _RecentActivity(colors: colors, theme: theme),
      ],
    );
  }
