/// Interactive Focus Timer — a real 25-minute pomodoro with start/pause/reset.
class _FocusTimerWidget extends StatefulWidget {
  const _FocusTimerWidget({
    required this.colors,
    required this.theme,
    required this.isLight,
  });

  final FahColors colors;
  final ThemeData theme;
  final bool isLight;

  @override
  State<_FocusTimerWidget> createState() => _FocusTimerWidgetState();
}

class _FocusTimerWidgetState extends State<_FocusTimerWidget> {
  static const _totalSeconds = 25 * 60; // 25:00
  var _remainingSeconds = _totalSeconds;
  Timer? _timer;
  var _running = false;

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  void _toggle() {
    if (_running) {
      _timer?.cancel();
      setState(() => _running = false);
    } else {
      _timer = Timer.periodic(const Duration(seconds: 1), (_) {
        if (_remainingSeconds <= 0) {
          _timer?.cancel();
          setState(() {
            _running = false;
            _remainingSeconds = _totalSeconds;
          });
          return;
        }
        setState(() => _remainingSeconds--);
      });
      setState(() => _running = true);
    }
  }

  void _reset() {
    _timer?.cancel();
    setState(() {
      _running = false;
      _remainingSeconds = _totalSeconds;
    });
  }

  String get _display {
    final m = (_remainingSeconds ~/ 60).toString().padLeft(2, '0');
    final s = (_remainingSeconds % 60).toString().padLeft(2, '0');
    return '$m:$s';
  }

  @override
  Widget build(BuildContext context) {
    final colors = widget.colors;
    final theme = widget.theme;
    final isLight = widget.isLight;
    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: isLight ? colors.panel : colors.panelAlt,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: colors.border),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            'Focus Timer',
            style: theme.textTheme.labelSmall?.copyWith(
              color: colors.dim,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 8),
          Center(
            child: Text(
              _display,
              style: theme.textTheme.headlineSmall?.copyWith(
                fontWeight: FontWeight.bold,
                color: _running ? colors.indigo : colors.pending,
              ),
            ),
          ),
          const SizedBox(height: 8),
          Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              // Start/Pause button.
              InkWell(
                onTap: _toggle,
                borderRadius: BorderRadius.circular(8),
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 16,
                    vertical: 6,
                  ),
                  decoration: BoxDecoration(
                    color: _running
                        ? colors.pending.withValues(alpha: 0.15)
                        : colors.indigo.withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Icon(
                        _running ? Icons.pause : Icons.play_arrow,
                        size: 16,
                        color: _running ? colors.pending : colors.indigo,
                      ),
                      const SizedBox(width: 4),
                      Text(
                        _running ? 'Pause' : 'Start',
                        style: theme.textTheme.bodySmall?.copyWith(
                          color: _running ? colors.pending : colors.indigo,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              const SizedBox(width: 8),
              // Reset button.
              InkWell(
                onTap: _reset,
                borderRadius: BorderRadius.circular(8),
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 6,
                  ),
                  child: Icon(Icons.replay, size: 16, color: colors.dim),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }
}

/// Section header with count.
class _SectionHeader extends StatelessWidget {
  const _SectionHeader({required this.title, required this.count});

  final String title;
  final int count;

  @override
  Widget build(BuildContext context) {
    final colors = FahColors.of(context);
    final theme = Theme.of(context);
    return Row(
      children: [
        Text(
          title,
          style: theme.textTheme.labelSmall?.copyWith(
            color: colors.dim,
            fontWeight: FontWeight.w600,
          ),
        ),
        const Spacer(),
        Text(
          '$count',
          style: theme.textTheme.bodySmall?.copyWith(color: colors.dim),
        ),
      ],
    );
  }
}

/// 4-column grid of app tiles. When [showAddTile] is true, an "Add app"
/// tile is appended (matching the prototype's "+" tile in the "Created by
/// you" section).
class _AppGrid extends StatelessWidget {
  const _AppGrid({
    required this.apps,
    required this.onTap,
    this.onLongPress,
    this.showAddTile = false,
    this.onAdd,
  });

  final List<JsAppInfo> apps;
  final ValueChanged<JsAppInfo> onTap;

  /// Long-press on a tile (context menu: open / remove).
  final void Function(JsAppInfo app, Offset globalPosition)? onLongPress;
  final bool showAddTile;

  /// The "Add widget" tile tap.
  final VoidCallback? onAdd;

  @override
  Widget build(BuildContext context) {
    final colors = FahColors.of(context);
    final theme = Theme.of(context);
    final isLight = theme.brightness == Brightness.light;
    return GridView.builder(
      shrinkWrap: true,
      physics: const NeverScrollableScrollPhysics(),
      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
        crossAxisCount: 4,
        childAspectRatio: 0.82,
        crossAxisSpacing: 8,
        mainAxisSpacing: 12,
      ),
      itemCount: apps.length + (showAddTile ? 1 : 0),
      itemBuilder: (context, index) {
        if (showAddTile && index == apps.length) {
          return _AddAppTile(
            colors: colors,
            theme: theme,
            isLight: isLight,
            onTap: onAdd,
          );
        }
        return _AppTile(
          app: apps[index],
          onTap: () => onTap(apps[index]),
          onLongPress: onLongPress == null
              ? null
              : (position) => onLongPress!(apps[index], position),
        );
      },
    );
  }
}

/// The "Add widget" tile at the end of the custom apps grid: asks Fa to
/// find a matching catalog widget or plan a new one.
class _AddAppTile extends StatelessWidget {
  const _AddAppTile({
    required this.colors,
    required this.theme,
    required this.isLight,
    required this.onTap,
  });

  final FahColors colors;
  final ThemeData theme;
  final bool isLight;
  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(12),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Container(
            width: 44,
            height: 44,
            decoration: BoxDecoration(
              color: isLight ? colors.panel : colors.panelAlt,
              borderRadius: BorderRadius.circular(11),
              border: Border.all(color: colors.border),
            ),
            child: Icon(Icons.add, size: 22, color: colors.indigo),
          ),
          const SizedBox(height: 6),
          Text(
            'Add widget',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: theme.textTheme.bodySmall?.copyWith(
              fontSize: 11,
              color: colors.indigo,
            ),
          ),
        ],
      ),
    );
  }
}

/// One app tile: rounded-square icon + label.
class _AppTile extends StatelessWidget {
  const _AppTile({required this.app, required this.onTap, this.onLongPress});

  final JsAppInfo app;
  final VoidCallback onTap;

  /// Long-press (context menu); carries the pointer position for the menu.
  final ValueChanged<Offset>? onLongPress;

  @override
  Widget build(BuildContext context) {
    final colors = FahColors.of(context);
    final theme = Theme.of(context);
    final isLight = theme.brightness == Brightness.light;
    final manager = context
        .dependOnInheritedWidgetOfExactType<ManagerScope>()
        ?.manager;
    final service = manager?.active?.service;
    return InkWell(
      onTap: onTap,
      onLongPress: onLongPress == null
          ? null
          : () {
              final box = context.findRenderObject();
              final center = box is RenderBox
                  ? box.localToGlobal(box.size.center(Offset.zero))
                  : Offset.zero;
              onLongPress!(center);
            },
      borderRadius: BorderRadius.circular(12),
      child: Column(
        mainAxisAlignment: MainAxisAlignment.center,
        children: [
          Container(
            width: 44,
            height: 44,
            decoration: BoxDecoration(
              color: isLight ? colors.panelAlt : colors.panel,
              borderRadius: BorderRadius.circular(11),
              border: Border.all(color: colors.border),
            ),
            child: Center(
              child: service != null
                  ? AppIcon(app: app, env: service.env, size: 24)
                  : AppIcon(app: app, env: manager!.env, size: 24),
            ),
          ),
          const SizedBox(height: 6),
          Text(
            app.displayName(Localizations.localeOf(context).toLanguageTag()),
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: theme.textTheme.bodySmall?.copyWith(
              fontSize: 11,
              color: colors.dim,
            ),
          ),
        ],
      ),
    );
  }
}

/// The System apps row (Calendar, Files, Notes, Maps, Calculator,
/// Settings, Utilities, Travel) was removed — these were grey placeholder
/// tiles that opened the corresponding system feature or did nothing.
/// Calendar / Weather / Contacts / Reminders / Health / Maps / Calculator
/// live as real JS apps in the apps store and surface under Demo apps
/// below; Files / Settings are real sidebar entries that open
/// [FileBrowser] / [SettingsScreen].

/// Recent activity footer.
class _RecentActivity extends StatelessWidget {
  const _RecentActivity({required this.colors, required this.theme});

  final FahColors colors;
  final ThemeData theme;

  @override
  Widget build(BuildContext context) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(
          'Recent activity',
          style: theme.textTheme.labelSmall?.copyWith(
            color: colors.dim,
            fontWeight: FontWeight.w600,
          ),
        ),
        const SizedBox(height: 8),
        _ActivityRow(
          icon: Icons.check_circle_outline,
          label: 'Checked Calendar',
          time: 'Just now',
          colors: colors,
          theme: theme,
        ),
        _ActivityRow(
          icon: Icons.folder_open,
          label: 'Opened Files',
          time: '10m ago',
          colors: colors,
          theme: theme,
        ),
      ],
    );
  }
}

class _ActivityRow extends StatelessWidget {
  const _ActivityRow({
    required this.icon,
    required this.label,
    required this.time,
    required this.colors,
    required this.theme,
  });

  final IconData icon;
  final String label;
  final String time;
  final FahColors colors;
  final ThemeData theme;

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 3),
      child: Row(
        children: [
          Icon(icon, size: 14, color: colors.dim),
          const SizedBox(width: 8),
          Expanded(
            child: Text(
              label,
              style: theme.textTheme.bodySmall?.copyWith(color: colors.dim),
            ),
          ),
          Text(
            time,
            style: theme.textTheme.bodySmall?.copyWith(
              color: colors.dim.withValues(alpha: 0.6),
              fontSize: 10,
            ),
          ),
        ],
      ),
    );
  }
}

/// Inherited widget so [_AppTile] can access the session manager for AppIcon.
class ManagerScope extends InheritedWidget {
  const ManagerScope({super.key, required this.manager, required super.child});

  final FlutterSessionManager manager;

  static ManagerScope? of(BuildContext context) =>
      context.dependOnInheritedWidgetOfExactType<ManagerScope>();

  @override
  bool updateShouldNotify(ManagerScope oldWidget) =>
      manager != oldWidget.manager;
}

